/* GENERATED by tools/build-bank.js from data/yaml/*.yml -- do not edit by hand. */
CS.addQuestions([
  {"id":"c01-1","card":1,"cardTitle":"What was this course about?","origin":"direct","tags":["conceptual","relational"],"prompt":"What are the big-picture **data modeling** concepts in this course?","answer":"* **Schema:** concepts related to organizing and modeling how your database stores data.\n* **CRUD:** concepts related to working with data within that schema."},
  {"id":"c01-2","card":1,"cardTitle":"What was this course about?","origin":"direct","tags":["conceptual","relational","document_db","key_value","graph_db"],"prompt":"What are the big-picture **database types** covered in this course?","answer":"Relational databases and NoSQL databases (document, key-value, and graph)."},
  {"id":"c01-3","card":1,"cardTitle":"What was this course about?","origin":"inferred","tags":["conceptual","table"],"prompt":"What does the word **schema** refer to?","answer":"The structure of a database: which tables exist, which columns each has, their types, and how the tables relate (keys and constraints)."},
  {"id":"c01-4","card":1,"cardTitle":"What was this course about?","origin":"inferred","tags":["conceptual","select","insert","update","delete"],"prompt":"CRUD stands for Create, Read, Update, Delete. Which SQL statement does each letter correspond to?","answer":"Create = `INSERT`, Read = `SELECT`, Update = `UPDATE`, Delete = `DELETE`."},
  {"id":"c01-5","card":1,"cardTitle":"What was this course about?","origin":"inferred","tags":["conceptual","relational","document_db","key_value","graph_db"],"prompt":"How do relational and NoSQL databases differ in what they trade off?","answer":"They trade off structure, flexibility, and scale differently: relational databases favor structure and integrity, while NoSQL stores (document, key-value, graph) favor flexibility or scale for particular access patterns."},
  {"id":"c02-1","card":2,"cardTitle":"What did you learn about SQL?","origin":"direct","tags":["conceptual","table","key","normalization","relational"],"prompt":"List the core relational concepts covered in this course.","answer":"Tables, rows, and keys; and normalization."},
  {"id":"c02-2","card":2,"cardTitle":"What did you learn about SQL?","origin":"direct","tags":["conceptual","create_table","select","where","join","insert","update","delete"],"prompt":"List the key SQL operations covered in this course, organized by schema and CRUD.","answer":"* **Schema:** `CREATE TABLE` / `DROP TABLE`\n* **CRUD:** `SELECT` / `WHERE` / `JOIN`, and `INSERT` / `UPDATE` / `DELETE`"},
  {"id":"c02-3","card":2,"cardTitle":"What did you learn about SQL?","origin":"inferred","tags":["conceptual","create_table","select","insert","update","delete"],"prompt":"Classify each statement as a schema operation or a CRUD operation: `CREATE TABLE`, `SELECT`, `DROP TABLE`, `UPDATE`.","answer":"`CREATE TABLE` and `DROP TABLE` are schema operations (they change the structure). `SELECT` and `UPDATE` are CRUD operations (they work with the data)."},
  {"id":"c02-4","card":2,"cardTitle":"What did you learn about SQL?","origin":"inferred","tags":["conceptual","select","insert","update","delete"],"prompt":"Which of `SELECT`, `INSERT`, `UPDATE`, and `DELETE` only read data, and which modify it?","answer":"`SELECT` only reads. `INSERT`, `UPDATE`, and `DELETE` modify the data."},
  {"id":"c02-5","card":2,"cardTitle":"What did you learn about SQL?","origin":"inferred","tags":["conceptual","normalization","anomaly"],"prompt":"In one sentence, what problem does normalization solve?","answer":"It minimizes redundancy so the same fact isn't stored in many places, preventing update and delete anomalies."},
  {"id":"c03-1","card":3,"cardTitle":"What did you learn about modeling?","origin":"direct","tags":["conceptual","table","relationship"],"prompt":"What is an **entity**?","answer":"A real-world (or app) thing you store data about, e.g. a Card or a Deck. A table holds rows representing instances of that entity."},
  {"id":"c03-2","card":3,"cardTitle":"What did you learn about modeling?","origin":"direct","tags":["conceptual","relationship","key"],"prompt":"What is a **relationship** between entities, and how is it stored?","answer":"A link between rows of different tables (e.g. a card belongs to a deck). Rows relate via foreign keys."},
  {"id":"c03-3","card":3,"cardTitle":"What did you learn about modeling?","origin":"direct","tags":["conceptual","relationship"],"prompt":"What kinds of relationships did we cover?","answer":"Has-many / belongs-to (one-to-many), and many-to-many through junction tables."},
  {"id":"c03-4","card":3,"cardTitle":"What did you learn about modeling?","origin":"direct","tags":["conceptual","normalization"],"prompt":"What's the point of normalization?","answer":"Good database hygiene: it keeps the model free of redundancy and anomalies."},
  {"id":"c03-5","card":3,"cardTitle":"What did you learn about modeling?","origin":"inferred","tags":["design","er_modeling","relationship"],"prompt":"A school stores students and classes. Name the entities and describe the relationship between them.","answer":"The entities are Student and Class. A student takes many classes and a class has many students, so it is a many-to-many relationship, stored in a junction table (e.g. `enrollments` with `student_id` and `class_id`)."},
  {"id":"c04-1","card":4,"cardTitle":"What skills did you practice?","origin":"direct","tags":["conceptual"],"prompt":"What is **fluent recall**?","answer":"Recalling something quickly and effortlessly, without needing to look it up."},
  {"id":"c04-2","card":4,"cardTitle":"What skills did you practice?","origin":"direct","tags":["conceptual"],"prompt":"What are \"knowledge skills\"? Give examples from this class.","answer":"Fluent recall of database concepts, e.g. What is a foreign key? What is normalization? What does JOIN do?"},
  {"id":"c04-3","card":4,"cardTitle":"What skills did you practice?","origin":"direct","tags":["conceptual"],"prompt":"What are the \"practical skills\" in this class?","answer":"Understanding SQL, schemas, and ER diagrams (reading), and writing them: translating a \"spec\" into SQL, a schema, and ER diagrams."},
  {"id":"c04-4","card":4,"cardTitle":"What skills did you practice?","origin":"inferred","tags":["conceptual"],"prompt":"Classify each as a knowledge skill or a practical skill: (a) saying what a primary key is without looking it up, (b) writing a query that joins two tables, (c) explaining what normalization is, (d) drawing an ER diagram from a description.","answer":"(a) knowledge, (b) practical, (c) knowledge, (d) practical."},
  {"id":"c04-5","card":4,"cardTitle":"What skills did you practice?","origin":"inferred","tags":["conceptual"],"prompt":"What is the difference between *understanding* and *writing* as practical skills in this class?","answer":"Understanding means reading and interpreting SQL, schemas and ER diagrams that exist. Writing means translating a spec into new SQL, schemas and ER diagrams."},
  {"id":"c05-1","card":5,"cardTitle":"What are tables/rows/queries?","origin":"direct","tags":["conceptual","table"],"prompt":"What is a **table**?","answer":"A named collection of rows, all with the same columns (e.g. `cards`)."},
  {"id":"c05-2","card":5,"cardTitle":"What are tables/rows/queries?","origin":"direct","tags":["conceptual","table"],"prompt":"What is a **row**?","answer":"One record/instance (e.g. one specific flashcard)."},
  {"id":"c05-3","card":5,"cardTitle":"What are tables/rows/queries?","origin":"direct","tags":["conceptual","table"],"prompt":"What is a **column**?","answer":"A named field that every row has (e.g. `question`, `answer`)."},
  {"id":"c05-4","card":5,"cardTitle":"What are tables/rows/queries?","origin":"direct","tags":["conceptual","key"],"prompt":"What is a **primary key**?","answer":"A column (or set of columns) that uniquely identifies each row."},
  {"id":"c05-5","card":5,"cardTitle":"What are tables/rows/queries?","origin":"direct","tags":["conceptual","select"],"prompt":"What does it mean to **query** a database?","answer":"To send it a request to retrieve, filter, or sort rows."},
  {"id":"c05-6","card":5,"cardTitle":"What are tables/rows/queries?","origin":"direct","tags":["conceptual","table"],"prompt":"What is the difference between a **database** and a **table**?","answer":"A database is a collection of related tables, e.g. one database holding `cards`, `decks`, `tags`, and `reviews`. A table is just one of them."},
  {"id":"c06-1","card":6,"cardTitle":"Syntax for SELECT/WHERE?","origin":"direct","tags":["syntax_pattern","select"],"prompt":"Write the syntax pattern for selecting all columns from a table.","answer":"```sql\nSELECT * FROM cards;\n```"},
  {"id":"c06-2","card":6,"cardTitle":"Syntax for SELECT/WHERE?","origin":"direct","tags":["syntax_pattern","select"],"prompt":"Write the syntax pattern for selecting specific columns.","answer":"```sql\nSELECT question, answer FROM cards;\n```"},
  {"id":"c06-3","card":6,"cardTitle":"Syntax for SELECT/WHERE?","origin":"direct","tags":["syntax_pattern","select","where"],"prompt":"Write the syntax pattern for filtering rows with `WHERE`.","answer":"```sql\nSELECT question, answer FROM cards\nWHERE created_at > '2026-01-01';\n```"},
  {"id":"c06-4","card":6,"cardTitle":"Syntax for SELECT/WHERE?","origin":"direct","tags":["writing_prompt","select","where"],"prompt":"Given a `cards` table with columns `id, question, answer, created_at`, write a query that selects the `question` and `answer` of every card created after '2026-01-01'.","answer":"```sql\nSELECT question, answer FROM cards\nWHERE created_at > '2026-01-01';\n```"},
  {"id":"c06-5","card":6,"cardTitle":"Syntax for SELECT/WHERE?","origin":"inferred","tags":["tracing","select","where"],"prompt":"Given this `cards` table, which `id`s does the query return?\n\n| id | question | created_at |\n|---|---|---|\n| 1 | What is a key? | 2025-12-31 |\n| 2 | What is a JOIN? | 2026-01-01 |\n| 3 | What is a row? | 2026-02-10 |\n| 4 | What is a table? | 2026-03-05 |\n\n```sql\nSELECT id FROM cards WHERE created_at > '2026-01-01';\n```","answer":"`3` and `4`. The comparison is strictly greater than, so card 2 (created exactly on 2026-01-01) is excluded."},
  {"id":"c06-6","card":6,"cardTitle":"Syntax for SELECT/WHERE?","origin":"inferred","tags":["conceptual","select"],"prompt":"What is the difference between `SELECT *` and `SELECT question, answer`?","answer":"`SELECT *` returns every column of the table; naming columns returns only those columns, in the order listed."},
  {"id":"c07-1","card":7,"cardTitle":"Syntax for ORDER BY/LIMIT?","origin":"direct","tags":["syntax_pattern","select","order_by"],"prompt":"Write the syntax pattern for sorting results with `ORDER BY`.","answer":"```sql\nSELECT question, created_at FROM cards\nORDER BY created_at;\n```"},
  {"id":"c07-2","card":7,"cardTitle":"Syntax for ORDER BY/LIMIT?","origin":"direct","tags":["syntax_pattern","select","order_by"],"prompt":"Write the syntax pattern for sorting descending.","answer":"```sql\nSELECT question, created_at FROM cards\nORDER BY created_at DESC;\n```"},
  {"id":"c07-3","card":7,"cardTitle":"Syntax for ORDER BY/LIMIT?","origin":"direct","tags":["syntax_pattern","select","limit"],"prompt":"Write the syntax pattern for limiting the number of rows returned.","answer":"```sql\nSELECT question FROM cards\nLIMIT 5;\n```"},
  {"id":"c07-4","card":7,"cardTitle":"Syntax for ORDER BY/LIMIT?","origin":"direct","tags":["writing_prompt","select","order_by","limit"],"prompt":"Write a query that returns the 5 most recently created cards, newest first.","answer":"```sql\nSELECT question, created_at FROM cards\nORDER BY created_at DESC\nLIMIT 5;\n```"},
  {"id":"c07-5","card":7,"cardTitle":"Syntax for ORDER BY/LIMIT?","origin":"inferred","tags":["tracing","select","order_by","limit"],"prompt":"Given this `cards` table, what does the query return, in order?\n\n| id | question | rating |\n|---|---|---|\n| 1 | A | 3 |\n| 2 | B | 5 |\n| 3 | C | 1 |\n| 4 | D | 4 |\n\n```sql\nSELECT question FROM cards ORDER BY rating DESC LIMIT 2;\n```","answer":"`B` then `D`: sorted by rating from highest to lowest (5, 4, 3, 1), and `LIMIT 2` keeps only the first two rows."},
  {"id":"c07-6","card":7,"cardTitle":"Syntax for ORDER BY/LIMIT?","origin":"inferred","tags":["conceptual","select","order_by","where","limit"],"prompt":"In what order do `WHERE`, `ORDER BY`, and `LIMIT` appear in a query?","answer":"`WHERE` first, then `ORDER BY`, then `LIMIT`:\n```sql\nSELECT ... FROM ... WHERE ... ORDER BY ... LIMIT ...;\n```"},
  {"id":"c08-1","card":8,"cardTitle":"Fluency with SELECT/WHERE?","origin":"inferred","tags":["design","create_table"],"prompt":"Design one table for a music playlist app's songs. Name the table and give its columns.","answer":"For example:\n```sql\nCREATE TABLE songs (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  artist TEXT,\n  duration_seconds INTEGER,\n  rating INTEGER\n);\n```"},
  {"id":"c08-2","card":8,"cardTitle":"Fluency with SELECT/WHERE?","origin":"inferred","tags":["writing_prompt","select","where","order_by"],"prompt":"Given `songs(id, title, artist, duration_seconds, rating)`, write a query for the titles of songs longer than 200 seconds, longest first.","answer":"```sql\nSELECT title FROM songs\nWHERE duration_seconds > 200\nORDER BY duration_seconds DESC;\n```"},
  {"id":"c08-3","card":8,"cardTitle":"Fluency with SELECT/WHERE?","origin":"inferred","tags":["tracing","select","where"],"prompt":"Using this table, which titles does each query return? (a) `... WHERE rating >= 4 AND duration_seconds < 200` (b) `... WHERE rating >= 4 OR duration_seconds < 200`\n\n| title | rating | duration_seconds |\n|---|---|---|\n| Alpha | 5 | 250 |\n| Beta | 4 | 180 |\n| Gamma | 2 | 150 |\n| Delta | 3 | 300 |","answer":"(a) only `Beta` (both conditions must hold). (b) `Alpha`, `Beta`, and `Gamma`: a row needs only one condition to hold."},
  {"id":"c08-4","card":8,"cardTitle":"Fluency with SELECT/WHERE?","origin":"inferred","tags":["conceptual","select","order_by"],"prompt":"A `code` column is stored as text and holds the values '9', '10', and '100'. In what order does `ORDER BY code` put them?","answer":"`'10'`, `'100'`, `'9'`. Text sorts alphabetically, character by character, not numerically."},
  {"id":"c08-5","card":8,"cardTitle":"Fluency with SELECT/WHERE?","origin":"inferred","tags":["writing_prompt","select","where","order_by","limit"],"prompt":"Add a `LIMIT` so this query returns only the three highest-rated songs: `SELECT title FROM songs ORDER BY rating DESC;`","answer":"```sql\nSELECT title FROM songs ORDER BY rating DESC LIMIT 3;\n```"},
  {"id":"c09-1","card":9,"cardTitle":"What are has-many/belongs-to?","origin":"direct","tags":["conceptual","key","relationship"],"prompt":"What is a **foreign key**?","answer":"A column that stores the primary key of a row in another table, linking the two."},
  {"id":"c09-2","card":9,"cardTitle":"What are has-many/belongs-to?","origin":"direct","tags":["conceptual","relationship"],"prompt":"What does it mean for a **deck** to **have many** cards?","answer":"One row (a deck) is referenced by many rows in another table (its cards)."},
  {"id":"c09-3","card":9,"cardTitle":"What are has-many/belongs-to?","origin":"direct","tags":["conceptual","relationship","key"],"prompt":"What does it mean for a **card** to **belong to** a deck?","answer":"A card references exactly one row in another table (its deck) via a foreign key."},
  {"id":"c09-4","card":9,"cardTitle":"What are has-many/belongs-to?","origin":"direct","tags":["conceptual","relationship","normalization"],"prompt":"Why store `deck_id` on `cards` instead of repeating the deck's name on every card?","answer":"Storing `deck_id` avoids repeating (duplicating) deck information on every card row."},
  {"id":"c09-5","card":9,"cardTitle":"What are has-many/belongs-to?","origin":"inferred","tags":["conceptual","relationship","key"],"prompt":"In a has-many relationship, which table gets the foreign key: the \"one\" side or the \"many\" side?","answer":"The \"many\" side (the belongs-to side). Each card row stores `deck_id`; the decks table does not store a list of cards."},
  {"id":"c10-1","card":10,"cardTitle":"Syntax for foreign keys?","origin":"direct","tags":["syntax_pattern","create_table","key"],"prompt":"Write the syntax pattern for creating a `decks` table.","answer":"```sql\nCREATE TABLE decks (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL\n);\n```"},
  {"id":"c10-2","card":10,"cardTitle":"Syntax for foreign keys?","origin":"direct","tags":["syntax_pattern","create_table","key","relationship"],"prompt":"Write the syntax pattern for creating a `cards` table with a foreign key to `decks`.","answer":"```sql\nCREATE TABLE cards (\n  id INTEGER PRIMARY KEY,\n  question TEXT NOT NULL,\n  answer TEXT NOT NULL,\n  deck_id INTEGER REFERENCES decks(id)\n);\n```"},
  {"id":"c10-3","card":10,"cardTitle":"Syntax for foreign keys?","origin":"direct","tags":["writing_prompt","create_table","relationship"],"prompt":"Create `decks` (id, name) and `cards` (id, question, answer, deck_id) where `deck_id` references `decks`.","answer":"```sql\nCREATE TABLE decks (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL\n);\n\nCREATE TABLE cards (\n  id INTEGER PRIMARY KEY,\n  question TEXT NOT NULL,\n  answer TEXT NOT NULL,\n  deck_id INTEGER REFERENCES decks(id)\n);\n```"},
  {"id":"c10-4","card":10,"cardTitle":"Syntax for foreign keys?","origin":"inferred","tags":["conceptual","create_table","relationship"],"prompt":"Why must `decks` be created before `cards` in this schema?","answer":"`cards.deck_id` references `decks(id)`, so the referenced table must already exist when the foreign key is declared."},
  {"id":"c10-5","card":10,"cardTitle":"Syntax for foreign keys?","origin":"inferred","tags":["conceptual","key","relationship"],"prompt":"What does `deck_id INTEGER REFERENCES decks(id)` tell the database?","answer":"Every value in `cards.deck_id` must be the `id` of an existing row in `decks` (or NULL). It links each card to its deck and lets the database enforce that link."},
  {"id":"c11-1","card":11,"cardTitle":"Syntax for inserting related rows?","origin":"direct","tags":["syntax_pattern","insert"],"prompt":"Write the syntax pattern for inserting a row into `decks`.","answer":"```sql\nINSERT INTO decks (id, name)\nVALUES (1, 'Databases 101');\n```"},
  {"id":"c11-2","card":11,"cardTitle":"Syntax for inserting related rows?","origin":"direct","tags":["syntax_pattern","insert","relationship"],"prompt":"Write the syntax pattern for inserting a row into `cards` that references that deck.","answer":"```sql\nINSERT INTO cards (id, question, answer, deck_id)\nVALUES (1, 'What is a primary key?', 'A column that uniquely identifies each row.', 1);\n```"},
  {"id":"c11-3","card":11,"cardTitle":"Syntax for inserting related rows?","origin":"direct","tags":["writing_prompt","insert","relationship"],"prompt":"Insert a deck \"Databases 101\" and one card in it: question \"What is a primary key?\", answer \"A column that uniquely identifies each row.\"","answer":"```sql\nINSERT INTO decks (id, name)\nVALUES (1, 'Databases 101');\n\nINSERT INTO cards (id, question, answer, deck_id)\nVALUES (1, 'What is a primary key?',\n        'A column that uniquely identifies each row.', 1);\n```"},
  {"id":"c11-4","card":11,"cardTitle":"Syntax for inserting related rows?","origin":"inferred","tags":["conceptual","insert","relationship"],"prompt":"Why must the deck be inserted before the card that belongs to it?","answer":"The card's `deck_id` must refer to a deck row that already exists."},
  {"id":"c11-5","card":11,"cardTitle":"Syntax for inserting related rows?","origin":"inferred","tags":["debugging","insert","relationship"],"prompt":"With only deck 1 in `decks`, what happens when you run the following, and why?\n```sql\nINSERT INTO cards (id, question, answer, deck_id)\nVALUES (2, 'What is a row?', 'One record.', 99);\n```","answer":"The insert is rejected with a foreign key violation: there is no deck with `id` 99, and `deck_id` must reference an existing deck."},
  {"id":"c12-1","card":12,"cardTitle":"Fluency with has-many/belongs-to?","origin":"inferred","tags":["design","create_table","relationship"],"prompt":"A gym has many members. Design the two tables and the foreign key.","answer":"```sql\nCREATE TABLE gyms (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL\n);\n\nCREATE TABLE members (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  gym_id INTEGER REFERENCES gyms(id)\n);\n```"},
  {"id":"c12-2","card":12,"cardTitle":"Fluency with has-many/belongs-to?","origin":"inferred","tags":["writing_prompt","insert","relationship"],"prompt":"Given `gyms(id, name)` and `members(id, name, gym_id)`, insert one gym and two members who belong to it.","answer":"```sql\nINSERT INTO gyms (id, name) VALUES (1, 'Downtown Gym');\nINSERT INTO members (id, name, gym_id) VALUES (1, 'Ada', 1), (2, 'Grace', 1);\n```"},
  {"id":"c12-3","card":12,"cardTitle":"Fluency with has-many/belongs-to?","origin":"inferred","tags":["conceptual","relationship"],"prompt":"In the gym schema, which table \"has many\" and which \"belongs to\"? Why doesn't the foreign key go the other way?","answer":"A gym has many members; a member belongs to a gym. The foreign key lives on `members` because each member row can point at exactly one gym. A gym row can't hold \"many\" gym ids in one column without breaking 1NF."},
  {"id":"c12-4","card":12,"cardTitle":"Fluency with has-many/belongs-to?","origin":"inferred","tags":["design","er_modeling","relationship"],"prompt":"Draw an ER diagram for a playlist that has many songs.","answer":"Two boxes, `playlists` (id, name) and `songs` (id, title, playlist_id), joined by a line labeled one-to-many: the \"one\" end at `playlists`, the \"many\" end at `songs`. (`songs.playlist_id` is the foreign key.)"},
  {"id":"c12-5","card":12,"cardTitle":"Fluency with has-many/belongs-to?","origin":"inferred","tags":["conceptual","relationship","insert","constraint"],"prompt":"What happens if you insert a row whose foreign key points to a row that doesn't exist?","answer":"The database rejects the insert with a foreign key constraint error, and the row is not saved."},
  {"id":"c12-6","card":12,"cardTitle":"Fluency with has-many/belongs-to?","origin":"inferred","tags":["conceptual","relationship","key"],"prompt":"State a rule for deciding which of two related tables gets the foreign key.","answer":"Put the foreign key on the \"many\" (belongs-to) side: the table whose rows each point at exactly one row of the other table."},
  {"id":"c13-1","card":13,"cardTitle":"What is a JOIN?","origin":"direct","tags":["conceptual","join"],"prompt":"What is a **JOIN**?","answer":"It combines rows from two tables based on a matching column (e.g. `cards.deck_id = decks.id`)."},
  {"id":"c13-2","card":13,"cardTitle":"What is a JOIN?","origin":"direct","tags":["conceptual","join","relationship"],"prompt":"Why can't you get a card's deck name by querying `cards` alone?","answer":"`cards` only has `deck_id`, a number. You need to JOIN to `decks` to get the deck's name."},
  {"id":"c13-3","card":13,"cardTitle":"What is a JOIN?","origin":"direct","tags":["conceptual","inner_join","left_join"],"prompt":"What is the difference between an **INNER JOIN** and a **LEFT JOIN**?","answer":"An INNER JOIN keeps only rows that match in both tables. A LEFT JOIN keeps all rows from the left table, matched or not."},
  {"id":"c13-4","card":13,"cardTitle":"What is a JOIN?","origin":"direct","tags":["conceptual","left_join"],"prompt":"What happens to a LEFT JOIN row when there is no match on the right side?","answer":"The row is kept, and the right-side columns come back as `NULL`."},
  {"id":"c13-5","card":13,"cardTitle":"What is a JOIN?","origin":"inferred","tags":["tracing","inner_join","left_join"],"prompt":"Given these tables, how many rows does `decks LEFT JOIN cards ON cards.deck_id = decks.id` return, and how many does the INNER JOIN version return?\n\n`decks`: (1, 'SQL'), (2, 'Joins'), (3, 'Graphs')\n`cards`: (10, deck_id 1), (11, deck_id 1), (12, deck_id 2)","answer":"The LEFT JOIN returns 4 rows: two for deck 1, one for deck 2, and one for deck 3 with `NULL` card columns. The INNER JOIN returns 3 rows (deck 3 has no cards, so it is dropped)."},
  {"id":"c14-1","card":14,"cardTitle":"Syntax for INNER JOIN?","origin":"direct","tags":["syntax_pattern","join","inner_join"],"prompt":"Write the syntax pattern for an `INNER JOIN` between two tables.","answer":"```sql\nSELECT a.col, b.col\nFROM a\nINNER JOIN b ON a.fk = b.id;\n```"},
  {"id":"c14-2","card":14,"cardTitle":"Syntax for INNER JOIN?","origin":"direct","tags":["syntax_pattern","join","inner_join","where"],"prompt":"Write the syntax pattern for an `INNER JOIN` with a `WHERE` clause.","answer":"```sql\nSELECT a.col, b.col\nFROM a\nINNER JOIN b ON a.fk = b.id\nWHERE b.col = 'x';\n```"},
  {"id":"c14-3","card":14,"cardTitle":"Syntax for INNER JOIN?","origin":"direct","tags":["writing_prompt","join","inner_join"],"prompt":"Write a query that lists every card's question alongside the name of the deck it belongs to.","answer":"```sql\nSELECT cards.question, decks.name\nFROM cards\nINNER JOIN decks ON cards.deck_id = decks.id;\n```"},
  {"id":"c14-4","card":14,"cardTitle":"Syntax for INNER JOIN?","origin":"inferred","tags":["writing_prompt","join","inner_join","where"],"prompt":"Write a query that lists the questions of the cards that belong to the deck named 'SQL'.","answer":"```sql\nSELECT cards.question\nFROM cards\nINNER JOIN decks ON cards.deck_id = decks.id\nWHERE decks.name = 'SQL';\n```"},
  {"id":"c14-5","card":14,"cardTitle":"Syntax for INNER JOIN?","origin":"inferred","tags":["debugging","join","inner_join"],"prompt":"What is wrong with this query?\n```sql\nSELECT cards.question, decks.name\nFROM cards\nINNER JOIN decks;\n```","answer":"The `ON` clause is missing, so the database can't tell which rows match. Add `ON cards.deck_id = decks.id`."},
  {"id":"c15-1","card":15,"cardTitle":"Syntax for LEFT JOIN?","origin":"direct","tags":["syntax_pattern","join","left_join"],"prompt":"Write the syntax pattern for a `LEFT JOIN`.","answer":"```sql\nSELECT a.col, b.col\nFROM a\nLEFT JOIN b ON b.fk = a.id;\n```"},
  {"id":"c15-2","card":15,"cardTitle":"Syntax for LEFT JOIN?","origin":"direct","tags":["syntax_pattern","join","left_join","where"],"prompt":"Write the syntax pattern for finding rows with no match (`IS NULL`).","answer":"```sql\nSELECT a.col\nFROM a\nLEFT JOIN b ON b.fk = a.id\nWHERE b.id IS NULL;\n```"},
  {"id":"c15-3","card":15,"cardTitle":"Syntax for LEFT JOIN?","origin":"direct","tags":["writing_prompt","join","left_join"],"prompt":"Write a query that lists every deck, including empty decks, alongside any card questions in it.","answer":"```sql\nSELECT decks.name, cards.question\nFROM decks\nLEFT JOIN cards ON cards.deck_id = decks.id;\n```"},
  {"id":"c15-4","card":15,"cardTitle":"Syntax for LEFT JOIN?","origin":"inferred","tags":["writing_prompt","join","left_join","where"],"prompt":"Write a query that lists the names of decks that have no cards.","answer":"```sql\nSELECT decks.name\nFROM decks\nLEFT JOIN cards ON cards.deck_id = decks.id\nWHERE cards.id IS NULL;\n```"},
  {"id":"c15-5","card":15,"cardTitle":"Syntax for LEFT JOIN?","origin":"inferred","tags":["conceptual","join","left_join","where"],"prompt":"Why do we test `cards.id IS NULL` rather than `cards.id = NULL` when looking for unmatched rows?","answer":"`NULL` means \"unknown\", and comparing anything to it with `=` is never true. `IS NULL` is the correct test."},
  {"id":"c16-1","card":16,"cardTitle":"Fluency with JOINs?","origin":"inferred","tags":["writing_prompt","join","inner_join"],"prompt":"Given `playlists(id, name)` and `songs(id, title, playlist_id)`, write an INNER JOIN that lists each song title with its playlist name.","answer":"```sql\nSELECT songs.title, playlists.name\nFROM songs\nINNER JOIN playlists ON songs.playlist_id = playlists.id;\n```"},
  {"id":"c16-2","card":16,"cardTitle":"Fluency with JOINs?","origin":"inferred","tags":["writing_prompt","join","left_join"],"prompt":"Given `playlists(id, name)` and `songs(id, title, playlist_id)`, write a LEFT JOIN that lists every playlist, including playlists with no songs.","answer":"```sql\nSELECT playlists.name, songs.title\nFROM playlists\nLEFT JOIN songs ON songs.playlist_id = playlists.id;\n```"},
  {"id":"c16-3","card":16,"cardTitle":"Fluency with JOINs?","origin":"inferred","tags":["writing_prompt","join","inner_join","relationship"],"prompt":"Given `students(id, name)`, `enrollments(student_id, class_id)` and `classes(id, title)`, write a query listing each student's name with the title of each class they take.","answer":"```sql\nSELECT students.name, classes.title\nFROM students\nINNER JOIN enrollments ON enrollments.student_id = students.id\nINNER JOIN classes ON classes.id = enrollments.class_id;\n```"},
  {"id":"c16-4","card":16,"cardTitle":"Fluency with JOINs?","origin":"inferred","tags":["writing_prompt","join","inner_join"],"prompt":"Rewrite this query using table aliases:\n```sql\nSELECT cards.question, decks.name\nFROM cards\nINNER JOIN decks ON cards.deck_id = decks.id;\n```","answer":"```sql\nSELECT c.question, d.name\nFROM cards c\nINNER JOIN decks d ON c.deck_id = d.id;\n```"},
  {"id":"c16-5","card":16,"cardTitle":"Fluency with JOINs?","origin":"inferred","tags":["tracing","join"],"prompt":"If you remove the `ON` condition from a join of a 3-row table and a 4-row table (using a form that allows it, such as `CROSS JOIN`), how many rows come back?","answer":"12 rows (3 x 4): every row of one table is paired with every row of the other."},
  {"id":"c16-6","card":16,"cardTitle":"Fluency with JOINs?","origin":"inferred","tags":["conceptual","join"],"prompt":"Which of these questions requires a JOIN to answer? (a) How many cards are there? (b) What is the name of the deck each card is in?","answer":"(b). The deck name is in the `decks` table and only `deck_id` is in `cards`. Question (a) needs just `cards`."},
  {"id":"c17-1","card":17,"cardTitle":"What is normalization?","origin":"direct","tags":["conceptual","normalization","anomaly"],"prompt":"What is **redundancy** in a database? Why is it a problem?","answer":"Redundancy is the same fact stored in more than one row (e.g. a tag's description copied onto every card that uses it). It wastes space and lets the copies disagree with each other."},
  {"id":"c17-2","card":17,"cardTitle":"What is normalization?","origin":"direct","tags":["conceptual","anomaly"],"prompt":"What is an **update anomaly**?","answer":"Fixing a typo in a duplicated fact requires updating many rows. Miss one, and the data disagrees with itself."},
  {"id":"c17-3","card":17,"cardTitle":"What is normalization?","origin":"direct","tags":["conceptual","anomaly"],"prompt":"What is a **delete anomaly**?","answer":"Deleting the only row that references some information deletes that information entirely, even if it is unrelated to what you meant to delete."},
  {"id":"c17-4","card":17,"cardTitle":"What is normalization?","origin":"direct","tags":["conceptual","normalization"],"prompt":"What is **normalization**?","answer":"Organizing tables to minimize redundancy and prevent update and delete anomalies."},
  {"id":"c17-5","card":17,"cardTitle":"What is normalization?","origin":"direct","tags":["conceptual","normalization","join"],"prompt":"What is the trade-off of normalizing \"too much\"?","answer":"Over-normalizing means more JOINs are needed to answer simple questions, a real performance and complexity cost."},
  {"id":"c17-6","card":17,"cardTitle":"What is normalization?","origin":"inferred","tags":["debugging","normalization","anomaly"],"prompt":"In this table, which columns are redundant, and which fact is repeated?\n\n| order_id | item | customer_name | customer_address |\n|---|---|---|---|\n| 1 | Pen | Ada | 12 Oak St |\n| 2 | Ink | Ada | 12 Oak St |\n| 3 | Pad | Grace | 9 Elm Ave |","answer":"`customer_name` and `customer_address` are redundant: Ada's address is stored once per order. The customer facts belong in a separate `customers` table."},
  {"id":"c18-1","card":18,"cardTitle":"Syntax for spotting redundancy?","origin":"direct","tags":["syntax_pattern","create_table","normalization"],"prompt":"Write a `cards` table that stores a tag name and tag description directly on every row (no `tags` table): an \"unnormalized\" version.","answer":"```sql\nCREATE TABLE cards_flat (\n  id INTEGER PRIMARY KEY,\n  question TEXT,\n  tag_name TEXT,\n  tag_description TEXT\n);\n```"},
  {"id":"c18-2","card":18,"cardTitle":"Syntax for spotting redundancy?","origin":"direct","tags":["conceptual","normalization","anomaly"],"prompt":"In `cards_flat (id, question, tag_name, tag_description)`, identify which columns are redundant.","answer":"`tag_name` and `tag_description` are repeated on every card that has that tag. The description depends on the tag, not on the card."},
  {"id":"c18-3","card":18,"cardTitle":"Syntax for spotting redundancy?","origin":"direct","tags":["writing_prompt","insert","anomaly"],"prompt":"Write two `INSERT` statements for `cards_flat (id, question, tag_name, tag_description)` that set up an update anomaly: both cards carry the same `tag_name`, but its description is typed two different ways.","answer":"```sql\nINSERT INTO cards_flat VALUES\n  (1, 'What is a for-loop?', 'loops',\n      'Repeats code a fixed number of times'),\n  (2, 'What is a while-loop?', 'loops',\n      'Repeats code while a condition holds');\n```\nThe same tag now has two different descriptions."},
  {"id":"c18-4","card":18,"cardTitle":"Syntax for spotting redundancy?","origin":"inferred","tags":["conceptual","anomaly"],"prompt":"Two rows are inserted into `cards_flat (id, question, tag_name, tag_description)`. Both have the `tag_name` 'loops', but one has the description 'Repeats code a fixed number of times' and the other 'Repeats code while a condition holds'. What is the \"truth\" about the description of the `loops` tag?","answer":"There is no single answer: the table now disagrees with itself. That is the problem an update anomaly causes."},
  {"id":"c18-5","card":18,"cardTitle":"Syntax for spotting redundancy?","origin":"inferred","tags":["tracing","anomaly","update"],"prompt":"1,000 rows in `cards_flat` carry the tag `loops` with the same description. How many rows must be updated to change that description? How many once it is in a `tags` table?","answer":"1,000 rows in `cards_flat`. In a normalized `tags` table it is stored once, so one row."},
  {"id":"c19-1","card":19,"cardTitle":"Syntax for splitting a table?","origin":"direct","tags":["syntax_pattern","create_table","normalization","relationship"],"prompt":"Write the syntax pattern for creating a normalized replacement of a flat table (two tables plus a foreign key).","answer":"```sql\nCREATE TABLE tags (\n  id INTEGER PRIMARY KEY,\n  name TEXT,\n  description TEXT\n);\n\nALTER TABLE cards ADD COLUMN tag_id INTEGER REFERENCES tags(id);\n```"},
  {"id":"c19-2","card":19,"cardTitle":"Syntax for splitting a table?","origin":"direct","tags":["syntax_pattern","update","normalization"],"prompt":"Write the syntax pattern for migrating data with `UPDATE`.","answer":"```sql\nUPDATE cards SET tag_id = 1 WHERE question LIKE '%loop%';\n```"},
  {"id":"c19-3","card":19,"cardTitle":"Syntax for splitting a table?","origin":"direct","tags":["writing_prompt","create_table","insert","update","normalization"],"prompt":"Refactor `cards_flat` into `tags` (id, name, description) and a `cards` table that references one tag by id.","answer":"```sql\nCREATE TABLE tags (\n  id INTEGER PRIMARY KEY,\n  name TEXT,\n  description TEXT\n);\n\nALTER TABLE cards ADD COLUMN tag_id INTEGER REFERENCES tags(id);\n\nINSERT INTO tags (id, name, description)\nVALUES (1, 'loops', 'Repeats code while a condition holds');\n\nUPDATE cards SET tag_id = 1 WHERE question LIKE '%loop%';\n```"},
  {"id":"c19-4","card":19,"cardTitle":"Syntax for splitting a table?","origin":"inferred","tags":["conceptual","normalization","update"],"prompt":"After `cards_flat` has been refactored into a `tags` table and a `cards` table that references it by `tag_id`, how do you correct the description of the `loops` tag?","answer":"With one update of one row:\n```sql\nUPDATE tags SET description = 'Repeats code' WHERE id = 1;\n```"},
  {"id":"c19-5","card":19,"cardTitle":"Syntax for splitting a table?","origin":"inferred","tags":["conceptual","update","where"],"prompt":"What does `WHERE question LIKE '%loop%'` match in the migration `UPDATE`?","answer":"Every card whose question contains the text \"loop\" anywhere in it (`%` matches any run of characters)."},
  {"id":"c20-1","card":20,"cardTitle":"Fluency with anomalies?","origin":"inferred","tags":["debugging","normalization","anomaly"],"prompt":"An `orders` table has columns `(order_id, product, customer_name, customer_address)`. Which columns are redundant, and why?","answer":"`customer_name` and `customer_address` repeat on every order that customer places, so the customer's facts are stored many times."},
  {"id":"c20-2","card":20,"cardTitle":"Fluency with anomalies?","origin":"inferred","tags":["writing_prompt","update","anomaly"],"prompt":"A flat `orders` table has the columns `(order_id, product, customer_name, customer_address)`. Show how an update anomaly could occur when the customer Ada moves to a new address.","answer":"```sql\nUPDATE orders SET customer_address = '5 Pine Rd'\nWHERE order_id = 1;\n```\nOnly order 1 was changed; Ada's other orders still list the old address, so the table now holds two addresses for one customer."},
  {"id":"c20-3","card":20,"cardTitle":"Fluency with anomalies?","origin":"inferred","tags":["writing_prompt","delete","anomaly"],"prompt":"A flat `orders` table has the columns `(order_id, product, customer_name, customer_address)`. Write a `DELETE` that would cause a delete anomaly.","answer":"```sql\nDELETE FROM orders WHERE order_id = 3;\n```\nIf order 3 is the only order for a customer (say Grace), deleting it also deletes everything the table knew about Grace, including her address."},
  {"id":"c20-4","card":20,"cardTitle":"Fluency with anomalies?","origin":"inferred","tags":["tracing","anomaly"],"prompt":"A customer's address is repeated in 40 orders. How many times does that fact appear, and how many rows must change if the address changes?","answer":"40 times; 40 rows."},
  {"id":"c20-5","card":20,"cardTitle":"Fluency with anomalies?","origin":"inferred","tags":["design","normalization","create_table"],"prompt":"Normalize the flat `orders` table `(order_id, product, customer_name, customer_address)` into separate tables.","answer":"```sql\nCREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT,\n  address TEXT\n);\n\nCREATE TABLE orders (\n  order_id INTEGER PRIMARY KEY,\n  product TEXT,\n  customer_id INTEGER REFERENCES customers(id)\n);\n```"},
  {"id":"c21-1","card":21,"cardTitle":"What are 1NF/2NF/3NF?","origin":"direct","tags":["conceptual","normalization"],"prompt":"What is **First Normal Form (1NF)**?","answer":"Every column holds a single value: no comma-separated lists in one cell (e.g. no `tags = \"loops, syntax\"`)."},
  {"id":"c21-2","card":21,"cardTitle":"What are 1NF/2NF/3NF?","origin":"direct","tags":["conceptual","normalization"],"prompt":"In 1NF, what does \"atomic\" mean?","answer":"A value that can't be meaningfully divided further: one value per cell, not a list."},
  {"id":"c21-3","card":21,"cardTitle":"What are 1NF/2NF/3NF?","origin":"direct","tags":["conceptual","normalization","key"],"prompt":"What is **Second Normal Form (2NF)**?","answer":"1NF, plus every non-key column depends on the *whole* primary key. This matters for multi-column keys."},
  {"id":"c21-4","card":21,"cardTitle":"What are 1NF/2NF/3NF?","origin":"direct","tags":["conceptual","normalization"],"prompt":"What is **Third Normal Form (3NF)**?","answer":"2NF, plus no non-key column depends on another non-key column (e.g. don't store `tag_category` derived from `tag_name` directly on `cards`)."},
  {"id":"c21-5","card":21,"cardTitle":"What are 1NF/2NF/3NF?","origin":"direct","tags":["debugging","normalization"],"prompt":"Give an example of data that violates 1NF.","answer":"A `cards` table with a `tags` column containing `\"loops, syntax\"` in one cell: a card can have more than one tag."},
  {"id":"c21-6","card":21,"cardTitle":"What are 1NF/2NF/3NF?","origin":"inferred","tags":["debugging","normalization","key"],"prompt":"A table `order_items (order_id, product_id, product_name, quantity)` has the composite primary key `(order_id, product_id)`. Which normal form does it violate and why?","answer":"2NF. `product_name` depends only on `product_id`, which is just part of the key. It should live in a `products` table."},
  {"id":"c21-7","card":21,"cardTitle":"What are 1NF/2NF/3NF?","origin":"inferred","tags":["debugging","normalization"],"prompt":"A `cards` table stores both `tag_name` and `tag_category`, where the category is determined by the tag name. Which normal form does it violate?","answer":"3NF: `tag_category` depends on another non-key column (`tag_name`) rather than directly on the key."},
  {"id":"c22-1","card":22,"cardTitle":"Syntax for fixing 1NF violations?","origin":"direct","tags":["syntax_pattern","create_table","relationship","normalization"],"prompt":"Write the syntax pattern for a junction table that replaces a comma-separated column.","answer":"```sql\nCREATE TABLE card_tags (\n  card_id INTEGER REFERENCES cards(id),\n  tag_id INTEGER REFERENCES tags(id),\n  PRIMARY KEY (card_id, tag_id)\n);\n```"},
  {"id":"c22-2","card":22,"cardTitle":"Syntax for fixing 1NF violations?","origin":"direct","tags":["syntax_pattern","insert","relationship"],"prompt":"Write the syntax pattern for inserting into a junction table.","answer":"```sql\nINSERT INTO card_tags (card_id, tag_id) VALUES (1, 1), (1, 2);\n```"},
  {"id":"c22-3","card":22,"cardTitle":"Syntax for fixing 1NF violations?","origin":"direct","tags":["writing_prompt","create_table","insert","normalization","relationship"],"prompt":"A `cards` table has a `tags` column like `'loops, syntax'`. Refactor it into `tags` and `card_tags` (junction) tables so one card can have many tags.","answer":"```sql\nCREATE TABLE tags (\n  id INTEGER PRIMARY KEY,\n  name TEXT UNIQUE\n);\n\nCREATE TABLE card_tags (\n  card_id INTEGER REFERENCES cards(id),\n  tag_id INTEGER REFERENCES tags(id),\n  PRIMARY KEY (card_id, tag_id)\n);\n\nINSERT INTO tags (id, name) VALUES (1, 'loops'), (2, 'syntax');\nINSERT INTO card_tags (card_id, tag_id) VALUES (1, 1), (1, 2);\n```"},
  {"id":"c22-4","card":22,"cardTitle":"Syntax for fixing 1NF violations?","origin":"inferred","tags":["conceptual","key","constraint"],"prompt":"Why is the primary key of `card_tags` the pair `(card_id, tag_id)`?","answer":"Each card/tag pair should appear at most once, and the pair itself uniquely identifies the row: it is a composite key."},
  {"id":"c22-5","card":22,"cardTitle":"Syntax for fixing 1NF violations?","origin":"inferred","tags":["conceptual","normalization"],"prompt":"Why is a comma-separated `tags` column hard to work with, even before thinking about normal forms?","answer":"You can't easily find all cards with a given tag, count tags, or enforce that tags exist: the database sees one text value, not separate values."},
  {"id":"c23-1","card":23,"cardTitle":"Syntax for many-to-many queries?","origin":"direct","tags":["syntax_pattern","join","inner_join","relationship"],"prompt":"Write the syntax pattern for joining through a junction table (two JOINs).","answer":"```sql\nSELECT a.col, b.col\nFROM a\nINNER JOIN a_b ON a_b.a_id = a.id\nINNER JOIN b ON b.id = a_b.b_id;\n```"},
  {"id":"c23-2","card":23,"cardTitle":"Syntax for many-to-many queries?","origin":"direct","tags":["syntax_pattern","join","inner_join","where"],"prompt":"Write the syntax pattern for listing all tags for one card.","answer":"```sql\nSELECT tags.name\nFROM card_tags\nINNER JOIN tags ON tags.id = card_tags.tag_id\nWHERE card_tags.card_id = 1;\n```"},
  {"id":"c23-3","card":23,"cardTitle":"Syntax for many-to-many queries?","origin":"direct","tags":["writing_prompt","join","inner_join","relationship"],"prompt":"Write a query that lists every card's question alongside each of its tag names.","answer":"```sql\nSELECT cards.question, tags.name\nFROM cards\nINNER JOIN card_tags ON card_tags.card_id = cards.id\nINNER JOIN tags ON tags.id = card_tags.tag_id;\n```"},
  {"id":"c23-4","card":23,"cardTitle":"Syntax for many-to-many queries?","origin":"inferred","tags":["tracing","join","inner_join"],"prompt":"Given the rows below, how many rows does this query return, and for which cards?\n\n```sql\nSELECT cards.question, tags.name\nFROM cards\nINNER JOIN card_tags ON card_tags.card_id = cards.id\nINNER JOIN tags ON tags.id = card_tags.tag_id;\n```\n\n`cards`: (1, 'A'), (2, 'B'), (3, 'C')\n`tags`: (1, 'loops'), (2, 'syntax')\n`card_tags`: (1, 1), (1, 2), (2, 2)","answer":"3 rows: card A with `loops`, card A with `syntax`, and card B with `syntax`. Card C has no `card_tags` rows, so the inner join drops it."},
  {"id":"c23-5","card":23,"cardTitle":"Syntax for many-to-many queries?","origin":"inferred","tags":["writing_prompt","join","inner_join","where"],"prompt":"Write a query that lists the questions of all cards tagged 'loops'.","answer":"```sql\nSELECT cards.question\nFROM cards\nINNER JOIN card_tags ON card_tags.card_id = cards.id\nINNER JOIN tags ON tags.id = card_tags.tag_id\nWHERE tags.name = 'loops';\n```"},
  {"id":"c24-1","card":24,"cardTitle":"Fluency with normal forms?","origin":"inferred","tags":["design","create_table","relationship","er_modeling"],"prompt":"Students take many classes and classes have many students. Design the tables, including the junction table.","answer":"```sql\nCREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT);\nCREATE TABLE classes  (id INTEGER PRIMARY KEY, title TEXT);\nCREATE TABLE enrollments (\n  student_id INTEGER REFERENCES students(id),\n  class_id INTEGER REFERENCES classes(id),\n  PRIMARY KEY (student_id, class_id)\n);\n```"},
  {"id":"c24-2","card":24,"cardTitle":"Fluency with normal forms?","origin":"inferred","tags":["writing_prompt","join","inner_join","relationship"],"prompt":"Write a query joining through `enrollments` that lists each student's name with the titles of their classes.","answer":"```sql\nSELECT students.name, classes.title\nFROM students\nINNER JOIN enrollments ON enrollments.student_id = students.id\nINNER JOIN classes ON classes.id = enrollments.class_id;\n```"},
  {"id":"c24-3","card":24,"cardTitle":"Fluency with normal forms?","origin":"inferred","tags":["tracing","relationship"],"prompt":"A student takes 3 classes. How many rows in `enrollments` represent that student?","answer":"3: one junction row per student/class pair."},
  {"id":"c24-4","card":24,"cardTitle":"Fluency with normal forms?","origin":"inferred","tags":["conceptual","normalization"],"prompt":"Check this against 1NF, 2NF, and 3NF in order: `students(id, name)` is split from `enrollments(student_id, class_id)`. Why does each normal form hold?","answer":"1NF: every cell holds a single value (one class per enrollment row). 2NF: the table has no non-key columns, so nothing depends on part of the key. 3NF: no non-key column depends on another non-key column."},
  {"id":"c24-5","card":24,"cardTitle":"Fluency with normal forms?","origin":"inferred","tags":["conceptual","normalization"],"prompt":"In plain language, what does 3NF say about a column that depends on another non-key column?","answer":"It shouldn't be there: move that fact (and the column it depends on) into its own table, so each non-key column depends only on the key."},
  {"id":"c25-1","card":25,"cardTitle":"What are keys/constraints?","origin":"direct","tags":["conceptual","key"],"prompt":"What is a **primary key**?","answer":"A column (or set of columns) that uniquely identifies each row. A table has exactly one primary key."},
  {"id":"c25-2","card":25,"cardTitle":"What are keys/constraints?","origin":"direct","tags":["conceptual","key"],"prompt":"Can more than one column form a table's primary key?","answer":"Yes: a primary key can span multiple columns."},
  {"id":"c25-3","card":25,"cardTitle":"What are keys/constraints?","origin":"direct","tags":["conceptual","key"],"prompt":"What is a **composite key**?","answer":"A primary key made of two or more columns together (e.g. `card_id + tag_id` in a junction table)."},
  {"id":"c25-4","card":25,"cardTitle":"What are keys/constraints?","origin":"direct","tags":["conceptual","constraint"],"prompt":"What does the `UNIQUE` constraint do?","answer":"No two rows may share the same value in that column."},
  {"id":"c25-5","card":25,"cardTitle":"What are keys/constraints?","origin":"direct","tags":["conceptual","constraint"],"prompt":"What does the `NOT NULL` constraint do?","answer":"The column can never be left empty."},
  {"id":"c25-6","card":25,"cardTitle":"What are keys/constraints?","origin":"direct","tags":["conceptual","constraint","insert"],"prompt":"What happens if you try to insert a row that violates a constraint?","answer":"The database rejects the INSERT/UPDATE with an error and the row is not saved."},
  {"id":"c26-1","card":26,"cardTitle":"Syntax for constraints?","origin":"direct","tags":["syntax_pattern","constraint"],"prompt":"Write the syntax pattern for a `UNIQUE` column.","answer":"```sql\nALTER TABLE tags ADD CONSTRAINT tags_name_unique UNIQUE (name);\n-- or inline: name TEXT UNIQUE\n```"},
  {"id":"c26-2","card":26,"cardTitle":"Syntax for constraints?","origin":"direct","tags":["syntax_pattern","constraint"],"prompt":"Write the syntax pattern for a `NOT NULL` column.","answer":"```sql\nALTER TABLE cards ALTER COLUMN question SET NOT NULL;\n-- or inline: question TEXT NOT NULL\n```"},
  {"id":"c26-3","card":26,"cardTitle":"Syntax for constraints?","origin":"direct","tags":["syntax_pattern","constraint","key"],"prompt":"Write the syntax pattern for a composite primary key.","answer":"```sql\nCREATE TABLE card_tags (\n  card_id INTEGER REFERENCES cards(id),\n  tag_id INTEGER REFERENCES tags(id),\n  PRIMARY KEY (card_id, tag_id)\n);\n```"},
  {"id":"c26-4","card":26,"cardTitle":"Syntax for constraints?","origin":"direct","tags":["writing_prompt","constraint"],"prompt":"Ensure `tags.name` must be unique, and `cards.question` and `cards.answer` can never be null.","answer":"```sql\nALTER TABLE tags ADD CONSTRAINT tags_name_unique UNIQUE (name);\n\nALTER TABLE cards ALTER COLUMN question SET NOT NULL;\nALTER TABLE cards ALTER COLUMN answer SET NOT NULL;\n```"},
  {"id":"c26-5","card":26,"cardTitle":"Syntax for constraints?","origin":"inferred","tags":["writing_prompt","create_table","constraint"],"prompt":"Write one `CREATE TABLE users` statement with columns `id`, `email`, and `name` where `id` is the primary key, `email` is unique, and `name` is required.","answer":"```sql\nCREATE TABLE users (\n  id INTEGER PRIMARY KEY,\n  email TEXT UNIQUE,\n  name TEXT NOT NULL\n);\n```"},
  {"id":"c27-1","card":27,"cardTitle":"Syntax for testing constraints?","origin":"direct","tags":["writing_prompt","insert","constraint"],"prompt":"Write an `INSERT` that would violate a `UNIQUE` constraint on `tags.name`, given that a tag named 'loops' already exists.","answer":"```sql\nINSERT INTO tags (name) VALUES ('loops');\n```\nIt fails because the name 'loops' is already used."},
  {"id":"c27-2","card":27,"cardTitle":"Syntax for testing constraints?","origin":"direct","tags":["writing_prompt","insert","constraint"],"prompt":"Write an `INSERT` into `cards` that would violate a `NOT NULL` constraint on `answer`.","answer":"```sql\nINSERT INTO cards (question, deck_id) VALUES ('What is a JOIN?', 1);\n```\nIt fails because `answer` is NOT NULL and no value was given."},
  {"id":"c27-3","card":27,"cardTitle":"Syntax for testing constraints?","origin":"direct","tags":["writing_prompt","insert","constraint"],"prompt":"Write two INSERT statements that each fail: one for a duplicate tag name, one for a card missing an answer.","answer":"```sql\n-- Fails: tag name already used\nINSERT INTO tags (name) VALUES ('loops');\n\n-- Fails: answer is NOT NULL\nINSERT INTO cards (question, deck_id) VALUES ('What is a JOIN?', 1);\n```"},
  {"id":"c27-4","card":27,"cardTitle":"Syntax for testing constraints?","origin":"inferred","tags":["conceptual","insert","constraint"],"prompt":"When an INSERT violates a constraint, what is the state of the table afterwards?","answer":"Unchanged: the statement is rejected with an error and no partial row is saved."},
  {"id":"c27-5","card":27,"cardTitle":"Syntax for testing constraints?","origin":"inferred","tags":["debugging","insert","key","constraint"],"prompt":"What happens when you insert a second row with the same primary key value as an existing row?","answer":"The insert fails with a duplicate (primary key / unique) violation, because a primary key must be unique."},
  {"id":"c28-1","card":28,"cardTitle":"Fluency with keys/constraints?","origin":"inferred","tags":["design","constraint","key"],"prompt":"A `members(id, email, name, joined_on)` table is being designed. Which columns need PRIMARY KEY, UNIQUE, and NOT NULL? Justify each.","answer":"`id` is the PRIMARY KEY (identifies a row). `email` should be UNIQUE (no two members share an email) and probably NOT NULL (it is how you contact them). `name` should be NOT NULL (a member must have a name). `joined_on` can be NOT NULL if every member has a join date."},
  {"id":"c28-2","card":28,"cardTitle":"Fluency with keys/constraints?","origin":"inferred","tags":["writing_prompt","create_table","constraint"],"prompt":"Write the full `CREATE TABLE` statement for `members(id, email, name, joined_on)` where `id` is the primary key, `email` is required and unique, and `name` and `joined_on` are required.","answer":"```sql\nCREATE TABLE members (\n  id INTEGER PRIMARY KEY,\n  email TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  joined_on TEXT NOT NULL\n);\n```"},
  {"id":"c28-3","card":28,"cardTitle":"Fluency with keys/constraints?","origin":"inferred","tags":["syntax_pattern","constraint"],"prompt":"Write the syntax for a `CHECK` constraint that requires a `rating` column to be between 1 and 5.","answer":"```sql\nrating INTEGER CHECK (rating BETWEEN 1 AND 5)\n```"},
  {"id":"c28-4","card":28,"cardTitle":"Fluency with keys/constraints?","origin":"inferred","tags":["syntax_pattern","constraint"],"prompt":"Write the syntax for a `DEFAULT` value that sets `joined_on` to a fixed date when none is given.","answer":"```sql\njoined_on TEXT DEFAULT '2026-01-01'\n```"},
  {"id":"c28-5","card":28,"cardTitle":"Fluency with keys/constraints?","origin":"inferred","tags":["conceptual","key"],"prompt":"When would a composite primary key need a third column? Give an example.","answer":"When the first two columns can legitimately repeat. For example, a student may take the same class in two different terms, so an `enrollments` key may need `(student_id, class_id, term)`."},
  {"id":"c29-1","card":29,"cardTitle":"What are INSERT/UPDATE/DELETE?","origin":"direct","tags":["conceptual","insert"],"prompt":"What does **INSERT** do?","answer":"It adds new row(s) to a table."},
  {"id":"c29-2","card":29,"cardTitle":"What are INSERT/UPDATE/DELETE?","origin":"direct","tags":["conceptual","update"],"prompt":"What does **UPDATE** do?","answer":"It changes existing column values on matching rows."},
  {"id":"c29-3","card":29,"cardTitle":"What are INSERT/UPDATE/DELETE?","origin":"direct","tags":["conceptual","delete"],"prompt":"What does **DELETE** do?","answer":"It removes matching rows entirely."},
  {"id":"c29-4","card":29,"cardTitle":"What are INSERT/UPDATE/DELETE?","origin":"direct","tags":["conceptual","update","delete","where"],"prompt":"Why is a `WHERE` clause critical on UPDATE and DELETE?","answer":"Without `WHERE`, UPDATE and DELETE apply to every row in the table."},
  {"id":"c29-5","card":29,"cardTitle":"What are INSERT/UPDATE/DELETE?","origin":"direct","tags":["conceptual","delete","where"],"prompt":"What happens if you run `DELETE FROM cards;` with no WHERE?","answer":"It deletes every flashcard in the table (every row)."},
  {"id":"c29-6","card":29,"cardTitle":"What are INSERT/UPDATE/DELETE?","origin":"direct","tags":["conceptual","update","delete","select","where"],"prompt":"What is a safe habit for testing UPDATE/DELETE before running them for real?","answer":"Run the equivalent `SELECT ... WHERE ...` first to see exactly which rows would be affected."},
  {"id":"c30-1","card":30,"cardTitle":"Syntax for INSERT/UPDATE?","origin":"direct","tags":["syntax_pattern","create_table","key","relationship"],"prompt":"Write the syntax pattern for a `reviews` table (id, card_id, reviewed_at, rating, next_review_date).","answer":"```sql\nCREATE TABLE reviews (\n  id INTEGER PRIMARY KEY,\n  card_id INTEGER REFERENCES cards(id),\n  reviewed_at TEXT,\n  rating INTEGER,\n  next_review_date TEXT\n);\n```"},
  {"id":"c30-2","card":30,"cardTitle":"Syntax for INSERT/UPDATE?","origin":"direct","tags":["syntax_pattern","insert"],"prompt":"Write the syntax pattern for `INSERT`.","answer":"```sql\nINSERT INTO reviews (card_id, reviewed_at, rating, next_review_date)\nVALUES (1, '2026-09-14', 4, '2026-09-17');\n```"},
  {"id":"c30-3","card":30,"cardTitle":"Syntax for INSERT/UPDATE?","origin":"direct","tags":["syntax_pattern","update"],"prompt":"Write the syntax pattern for `UPDATE`.","answer":"```sql\nUPDATE reviews\nSET rating = 5\nWHERE id = 1;\n```"},
  {"id":"c30-4","card":30,"cardTitle":"Syntax for INSERT/UPDATE?","origin":"direct","tags":["writing_prompt","create_table","insert"],"prompt":"Create `reviews`, then \"study\" card #1 by inserting a review with a rating and a next review date 3 days out.","answer":"```sql\nCREATE TABLE reviews (\n  id INTEGER PRIMARY KEY,\n  card_id INTEGER REFERENCES cards(id),\n  reviewed_at TEXT,\n  rating INTEGER,           -- e.g. 1 (hard) - 5 (easy)\n  next_review_date TEXT\n);\n\nINSERT INTO reviews (card_id, reviewed_at, rating, next_review_date)\nVALUES (1, '2026-09-14', 4, '2026-09-17');\n```"},
  {"id":"c30-5","card":30,"cardTitle":"Syntax for INSERT/UPDATE?","origin":"inferred","tags":["tracing","update","where"],"prompt":"A `reviews` table has ratings 2, 3, 5 for ids 1, 2, 3. After `UPDATE reviews SET rating = rating + 1 WHERE rating < 5;`, what are the ratings?","answer":"3, 4, 5. Ids 1 and 2 matched (rating below 5) and were increased by one; id 3 was left alone."},
  {"id":"c31-1","card":31,"cardTitle":"Syntax for DELETE?","origin":"direct","tags":["syntax_pattern","update","where"],"prompt":"Write the syntax pattern for an `UPDATE` that corrects a mis-entered rating.","answer":"```sql\nUPDATE reviews\nSET rating = 5\nWHERE id = 1;\n```"},
  {"id":"c31-2","card":31,"cardTitle":"Syntax for DELETE?","origin":"direct","tags":["syntax_pattern","delete","where"],"prompt":"Write the syntax pattern for `DELETE` with a `WHERE` clause.","answer":"```sql\nDELETE FROM reviews\nWHERE reviewed_at < '2025-01-01';\n```"},
  {"id":"c31-3","card":31,"cardTitle":"Syntax for DELETE?","origin":"direct","tags":["writing_prompt","update","delete"],"prompt":"Write an UPDATE that fixes review #1's rating to 5, then a DELETE that removes any review older than 2025-01-01.","answer":"```sql\nUPDATE reviews\nSET rating = 5\nWHERE id = 1;\n\nDELETE FROM reviews\nWHERE reviewed_at < '2025-01-01';\n```"},
  {"id":"c31-4","card":31,"cardTitle":"Syntax for DELETE?","origin":"inferred","tags":["tracing","delete","where"],"prompt":"`reviews` has `reviewed_at` values 2024-12-31, 2025-01-01, and 2025-06-01. Which rows does `DELETE FROM reviews WHERE reviewed_at < '2025-01-01';` remove?","answer":"Only the 2024-12-31 row. The 2025-01-01 row is not strictly less than the cutoff."},
  {"id":"c31-5","card":31,"cardTitle":"Syntax for DELETE?","origin":"inferred","tags":["writing_prompt","select","delete","where"],"prompt":"Write the `SELECT` you would run first to see which rows `DELETE FROM reviews WHERE reviewed_at < '2025-01-01';` would remove.","answer":"```sql\nSELECT * FROM reviews\nWHERE reviewed_at < '2025-01-01';\n```"},
  {"id":"c31-6","card":31,"cardTitle":"Syntax for DELETE?","origin":"inferred","tags":["debugging","update","where"],"prompt":"What is wrong with `UPDATE reviews SET rating = 5;` if the goal was to fix one review?","answer":"There is no `WHERE`, so every review's rating becomes 5. Add `WHERE id = 1`."},
  {"id":"c32-1","card":32,"cardTitle":"Fluency with INSERT/UPDATE?","origin":"inferred","tags":["design","create_table","insert"],"prompt":"Design a table for gym check-ins (an \"event log\").","answer":"```sql\nCREATE TABLE checkins (\n  id INTEGER PRIMARY KEY,\n  member_id INTEGER REFERENCES members(id),\n  checked_in_at TEXT NOT NULL\n);\n```"},
  {"id":"c32-2","card":32,"cardTitle":"Fluency with INSERT/UPDATE?","origin":"inferred","tags":["writing_prompt","insert","update","delete"],"prompt":"Write an INSERT that records a check-in for member 7, an UPDATE that corrects its time, and a DELETE that removes it. Use `checkins(id, member_id, checked_in_at)`.","answer":"```sql\nINSERT INTO checkins (member_id, checked_in_at) VALUES (7, '2026-10-05 09:00');\nUPDATE checkins SET checked_in_at = '2026-10-05 09:15' WHERE id = 1;\nDELETE FROM checkins WHERE id = 1;\n```"},
  {"id":"c32-3","card":32,"cardTitle":"Fluency with INSERT/UPDATE?","origin":"inferred","tags":["writing_prompt","update","where"],"prompt":"Write an UPDATE that affects only check-ins that match two conditions: member 7 and before 2026-01-01. Set `checked_in_at` to '2026-01-01 00:00'.","answer":"```sql\nUPDATE checkins\nSET checked_in_at = '2026-01-01 00:00'\nWHERE member_id = 7 AND checked_in_at < '2026-01-01';\n```"},
  {"id":"c32-4","card":32,"cardTitle":"Fluency with INSERT/UPDATE?","origin":"inferred","tags":["writing_prompt","delete","where"],"prompt":"Write a DELETE that removes only check-ins older than 2025-01-01.","answer":"```sql\nDELETE FROM checkins WHERE checked_in_at < '2025-01-01';\n```"},
  {"id":"c32-5","card":32,"cardTitle":"Fluency with INSERT/UPDATE?","origin":"inferred","tags":["writing_prompt","select","aggregate","where"],"prompt":"Write a `SELECT` that counts how many rows an `UPDATE checkins ... WHERE member_id = 7` would affect.","answer":"```sql\nSELECT COUNT(*) FROM checkins WHERE member_id = 7;\n```"},
  {"id":"c33-1","card":33,"cardTitle":"What is GROUP BY?","origin":"direct","tags":["conceptual","group_by"],"prompt":"What does **GROUP BY** do?","answer":"It collapses rows sharing a value into one summary row per group."},
  {"id":"c33-2","card":33,"cardTitle":"What is GROUP BY?","origin":"direct","tags":["conceptual","group_by","order_by"],"prompt":"How is GROUP BY different from ORDER BY?","answer":"ORDER BY just reorders rows; it doesn't merge them. GROUP BY merges rows into groups."},
  {"id":"c33-3","card":33,"cardTitle":"What is GROUP BY?","origin":"direct","tags":["conceptual","aggregate"],"prompt":"What are **aggregate functions**? Name a few.","answer":"Functions that compute one value from many rows: `COUNT`, `SUM`, `AVG`, `MIN`, `MAX`."},
  {"id":"c33-4","card":33,"cardTitle":"What is GROUP BY?","origin":"direct","tags":["conceptual","having","where","group_by"],"prompt":"What does **HAVING** do, and how is it different from **WHERE**?","answer":"HAVING filters *groups* (after aggregation); WHERE filters individual rows (before aggregation)."},
  {"id":"c33-5","card":33,"cardTitle":"What is GROUP BY?","origin":"direct","tags":["conceptual","where","aggregate","having"],"prompt":"Why can't you filter on an aggregate with WHERE?","answer":"WHERE runs before grouping happens, so the aggregate value doesn't exist yet to filter on. Use HAVING."},
  {"id":"c34-1","card":34,"cardTitle":"Syntax for GROUP BY/COUNT?","origin":"direct","tags":["syntax_pattern","group_by","aggregate"],"prompt":"Write the syntax pattern for `GROUP BY` with `COUNT`.","answer":"```sql\nSELECT deck_id, COUNT(*) AS num_cards\nFROM cards\nGROUP BY deck_id;\n```"},
  {"id":"c34-2","card":34,"cardTitle":"Syntax for GROUP BY/COUNT?","origin":"direct","tags":["syntax_pattern","group_by","aggregate"],"prompt":"Write the syntax pattern for `GROUP BY` with more than one aggregate function.","answer":"```sql\nSELECT card_id, COUNT(*) AS times, AVG(rating) AS avg_rating, MAX(rating) AS best\nFROM reviews\nGROUP BY card_id;\n```"},
  {"id":"c34-3","card":34,"cardTitle":"Syntax for GROUP BY/COUNT?","origin":"direct","tags":["writing_prompt","join","left_join","group_by","aggregate"],"prompt":"Write a query showing each card's question alongside how many times it has been reviewed.","answer":"```sql\nSELECT cards.question, COUNT(reviews.id) AS times_reviewed\nFROM cards\nLEFT JOIN reviews ON reviews.card_id = cards.id\nGROUP BY cards.id, cards.question;\n```"},
  {"id":"c34-4","card":34,"cardTitle":"Syntax for GROUP BY/COUNT?","origin":"inferred","tags":["tracing","group_by","aggregate"],"prompt":"Given `cards(id, deck_id)` with rows (1,1), (2,1), (3,2), (4,1), what does `SELECT deck_id, COUNT(*) FROM cards GROUP BY deck_id;` return?","answer":"Two rows: deck 1 with count 3, and deck 2 with count 1."},
  {"id":"c34-5","card":34,"cardTitle":"Syntax for GROUP BY/COUNT?","origin":"inferred","tags":["conceptual","left_join","group_by","aggregate"],"prompt":"In a query that LEFT JOINs `cards` to `reviews` and counts how many times each card has been reviewed, why is it `COUNT(reviews.id)` and not `COUNT(*)`?","answer":"With a LEFT JOIN, a card with no reviews still produces one row (with NULL review columns). `COUNT(*)` would count that row as 1; `COUNT(reviews.id)` ignores NULLs and correctly gives 0."},
  {"id":"c35-1","card":35,"cardTitle":"Syntax for HAVING?","origin":"direct","tags":["syntax_pattern","having","group_by"],"prompt":"Write the syntax pattern for `HAVING` after `GROUP BY`.","answer":"```sql\nSELECT deck_id, COUNT(*) AS num_cards\nFROM cards\nGROUP BY deck_id\nHAVING COUNT(*) > 10;\n```"},
  {"id":"c35-2","card":35,"cardTitle":"Syntax for HAVING?","origin":"direct","tags":["syntax_pattern","where","group_by","having"],"prompt":"Write the syntax pattern combining `WHERE`, `GROUP BY`, and `HAVING` in one query.","answer":"```sql\nSELECT deck_id, COUNT(*) AS num_cards\nFROM cards\nWHERE created_at > '2026-01-01'\nGROUP BY deck_id\nHAVING COUNT(*) > 10;\n```"},
  {"id":"c35-3","card":35,"cardTitle":"Syntax for HAVING?","origin":"direct","tags":["writing_prompt","join","inner_join","group_by","aggregate","having"],"prompt":"Write a query showing only cards whose average rating is below 3: the ones you're struggling with.","answer":"```sql\nSELECT cards.question, AVG(reviews.rating) AS avg_rating\nFROM cards\nINNER JOIN reviews ON reviews.card_id = cards.id\nGROUP BY cards.id, cards.question\nHAVING AVG(reviews.rating) < 3;\n```"},
  {"id":"c35-4","card":35,"cardTitle":"Syntax for HAVING?","origin":"inferred","tags":["debugging","where","aggregate","having"],"prompt":"This query fails. Why, and how do you fix it?\n```sql\nSELECT deck_id, COUNT(*) FROM cards\nWHERE COUNT(*) > 10\nGROUP BY deck_id;\n```","answer":"`WHERE` can't use an aggregate because it runs before grouping. Move the condition to `HAVING COUNT(*) > 10` after the `GROUP BY`."},
  {"id":"c35-5","card":35,"cardTitle":"Syntax for HAVING?","origin":"inferred","tags":["tracing","group_by","aggregate","having"],"prompt":"`reviews` has (card 1: ratings 2, 3), (card 2: ratings 5, 4), (card 3: rating 1). Which card ids does `SELECT card_id FROM reviews GROUP BY card_id HAVING AVG(rating) < 3;` return?","answer":"Cards 1 and 3: card 1 averages 2.5, card 3 averages 1, and card 2 averages 4.5."},
  {"id":"c36-1","card":36,"cardTitle":"Fluency with GROUP BY?","origin":"inferred","tags":["writing_prompt","group_by","aggregate"],"prompt":"Using `checkins(id, member_id, checked_in_at)`, write a query that shows how many check-ins each member has.","answer":"```sql\nSELECT member_id, COUNT(*) AS visits\nFROM checkins\nGROUP BY member_id;\n```"},
  {"id":"c36-2","card":36,"cardTitle":"Fluency with GROUP BY?","origin":"inferred","tags":["writing_prompt","group_by","aggregate","having"],"prompt":"Using `checkins(id, member_id, checked_in_at)`, write a query that shows how many check-ins each member has, but only for members with at least 10 check-ins.","answer":"```sql\nSELECT member_id, COUNT(*) AS visits\nFROM checkins\nGROUP BY member_id\nHAVING COUNT(*) >= 10;\n```"},
  {"id":"c36-3","card":36,"cardTitle":"Fluency with GROUP BY?","origin":"inferred","tags":["writing_prompt","group_by","aggregate"],"prompt":"Using `sales(id, region, amount)`, write a query for the total amount sold in each region.","answer":"```sql\nSELECT region, SUM(amount) AS total\nFROM sales\nGROUP BY region;\n```"},
  {"id":"c36-4","card":36,"cardTitle":"Fluency with GROUP BY?","origin":"inferred","tags":["writing_prompt","group_by","aggregate"],"prompt":"Using `sales(id, region, amount)`, write a query that shows the smallest and largest sale in each region.","answer":"```sql\nSELECT region, MIN(amount) AS smallest, MAX(amount) AS largest\nFROM sales\nGROUP BY region;\n```"},
  {"id":"c36-5","card":36,"cardTitle":"Fluency with GROUP BY?","origin":"inferred","tags":["conceptual","where","group_by","having"],"prompt":"In a query with WHERE, GROUP BY and HAVING, in what order do they run, and why does HAVING come after WHERE?","answer":"WHERE filters rows first, then GROUP BY forms groups, then HAVING filters the groups. HAVING needs the aggregates that only exist after grouping."},
  {"id":"c37-1","card":37,"cardTitle":"What are subqueries?","origin":"direct","tags":["conceptual","subquery"],"prompt":"What is a **subquery**?","answer":"A query nested inside another query."},
  {"id":"c37-2","card":37,"cardTitle":"What are subqueries?","origin":"direct","tags":["conceptual","subquery"],"prompt":"Where can a subquery appear?","answer":"Often in `WHERE`, `FROM`, or `SELECT`."},
  {"id":"c37-3","card":37,"cardTitle":"What are subqueries?","origin":"direct","tags":["conceptual","subquery"],"prompt":"What is a **correlated subquery**? How is it different from a regular subquery?","answer":"A correlated subquery references a column from the outer query, so it re-runs once per outer row. A regular subquery doesn't depend on the outer query and runs once."},
  {"id":"c37-4","card":37,"cardTitle":"What are subqueries?","origin":"direct","tags":["conceptual","set_operation"],"prompt":"What does **UNION** do?","answer":"It combines the results of two queries, removing duplicates."},
  {"id":"c37-5","card":37,"cardTitle":"What are subqueries?","origin":"direct","tags":["conceptual","set_operation"],"prompt":"What does **INTERSECT** do?","answer":"It returns only rows that appear in both queries' results."},
  {"id":"c37-6","card":37,"cardTitle":"What are subqueries?","origin":"direct","tags":["conceptual","set_operation"],"prompt":"What does **EXCEPT** do?","answer":"It returns rows in the first query's results but not the second's."},
  {"id":"c37-7","card":37,"cardTitle":"What are subqueries?","origin":"direct","tags":["conceptual","subquery","join"],"prompt":"When would you reach for a subquery instead of a JOIN?","answer":"When the question is naturally \"rows where some condition about *other* rows holds\", e.g. \"cards never reviewed\"."},
  {"id":"c38-1","card":38,"cardTitle":"Syntax for subqueries?","origin":"direct","tags":["syntax_pattern","subquery","where"],"prompt":"Write the syntax pattern for a subquery inside a `WHERE ... IN`.","answer":"```sql\nSELECT question FROM cards\nWHERE id IN (\n  SELECT card_id FROM reviews\n);\n```"},
  {"id":"c38-2","card":38,"cardTitle":"Syntax for subqueries?","origin":"direct","tags":["syntax_pattern","subquery","where"],"prompt":"Write the syntax pattern for a subquery inside a `WHERE ... NOT IN`.","answer":"```sql\nSELECT question FROM cards\nWHERE id NOT IN (\n  SELECT card_id FROM reviews\n);\n```"},
  {"id":"c38-3","card":38,"cardTitle":"Syntax for subqueries?","origin":"direct","tags":["writing_prompt","subquery","where"],"prompt":"Write a query that finds every card that has never been reviewed.","answer":"```sql\nSELECT question FROM cards\nWHERE id NOT IN (\n  SELECT card_id FROM reviews\n);\n```"},
  {"id":"c38-4","card":38,"cardTitle":"Syntax for subqueries?","origin":"inferred","tags":["tracing","subquery"],"prompt":"`cards` has ids 1, 2, 3, 4 and `reviews.card_id` contains 1, 1, 3. Which cards does the \"never reviewed\" query return?","answer":"Cards 2 and 4."},
  {"id":"c38-5","card":38,"cardTitle":"Syntax for subqueries?","origin":"inferred","tags":["writing_prompt","subquery","left_join","join"],"prompt":"Rewrite the \"never reviewed\" query using a LEFT JOIN instead of a subquery.","answer":"```sql\nSELECT cards.question\nFROM cards\nLEFT JOIN reviews ON reviews.card_id = cards.id\nWHERE reviews.id IS NULL;\n```"},
  {"id":"c39-1","card":39,"cardTitle":"Syntax for UNION/set operations?","origin":"direct","tags":["syntax_pattern","set_operation"],"prompt":"Write the syntax pattern for `UNION` between two SELECTs.","answer":"```sql\nSELECT question FROM cards WHERE deck_id = 1\nUNION\nSELECT question FROM cards WHERE deck_id = 2;\n```"},
  {"id":"c39-2","card":39,"cardTitle":"Syntax for UNION/set operations?","origin":"direct","tags":["syntax_pattern","set_operation"],"prompt":"Write the syntax pattern for `INTERSECT`.","answer":"```sql\nSELECT question FROM cards WHERE deck_id = 1\nINTERSECT\nSELECT question FROM cards WHERE rating >= 4;\n```"},
  {"id":"c39-3","card":39,"cardTitle":"Syntax for UNION/set operations?","origin":"direct","tags":["writing_prompt","set_operation","subquery","group_by","having"],"prompt":"Write a query returning a \"needs attention\" study queue: cards due for review on or before 2026-09-14 OR cards with an average rating below 3.","answer":"```sql\nSELECT question FROM cards\nWHERE id IN (\n  SELECT card_id FROM reviews\n  WHERE next_review_date <= '2026-09-14'\n)\nUNION\nSELECT question FROM cards\nWHERE id IN (\n  SELECT card_id FROM reviews\n  GROUP BY card_id\n  HAVING AVG(rating) < 3\n);\n```"},
  {"id":"c39-4","card":39,"cardTitle":"Syntax for UNION/set operations?","origin":"inferred","tags":["conceptual","set_operation"],"prompt":"What is the difference between `UNION` and `UNION ALL`?","answer":"`UNION` removes duplicate rows from the combined result; `UNION ALL` keeps every row, duplicates included."},
  {"id":"c39-5","card":39,"cardTitle":"Syntax for UNION/set operations?","origin":"inferred","tags":["tracing","set_operation"],"prompt":"Query A returns {1, 2, 3} and query B returns {2, 3, 4}. What do `UNION`, `INTERSECT`, and `A EXCEPT B` return?","answer":"`UNION` = {1, 2, 3, 4}; `INTERSECT` = {2, 3}; `A EXCEPT B` = {1}."},
  {"id":"c40-1","card":40,"cardTitle":"Fluency with subqueries/set ops?","origin":"inferred","tags":["writing_prompt","subquery","where"],"prompt":"Given `products(id, name)` and `order_items(product_id, order_id)`, write a query for products that were never ordered.","answer":"```sql\nSELECT name FROM products\nWHERE id NOT IN (SELECT product_id FROM order_items);\n```"},
  {"id":"c40-2","card":40,"cardTitle":"Fluency with subqueries/set ops?","origin":"inferred","tags":["writing_prompt","set_operation"],"prompt":"Write a UNION that combines \"customers in Seattle\" and \"customers with more than 5 orders\" into one list of names. Use `customers(name, city, order_count)`.","answer":"```sql\nSELECT name FROM customers WHERE city = 'Seattle'\nUNION\nSELECT name FROM customers WHERE order_count > 5;\n```"},
  {"id":"c40-3","card":40,"cardTitle":"Fluency with subqueries/set ops?","origin":"inferred","tags":["writing_prompt","subquery","where"],"prompt":"Given `products(id, name)` and `order_items(product_id, order_id)`, write a `WHERE ... IN` subquery that finds products that *were* ordered, and say how the result relates to the products a `NOT IN` version returns.","answer":"```sql\nSELECT name FROM products\nWHERE id IN (SELECT product_id FROM order_items);\n```\nIt returns exactly the products the `NOT IN` version leaves out."},
  {"id":"c40-4","card":40,"cardTitle":"Fluency with subqueries/set ops?","origin":"inferred","tags":["writing_prompt","set_operation"],"prompt":"Use `EXCEPT` to find product ids that appear in `products` but not in `order_items`.","answer":"```sql\nSELECT id FROM products\nEXCEPT\nSELECT product_id FROM order_items;\n```"},
  {"id":"c40-5","card":40,"cardTitle":"Fluency with subqueries/set ops?","origin":"inferred","tags":["writing_prompt","subquery","where","aggregate"],"prompt":"Write a correlated subquery that finds each employee earning more than the average salary of their own department. Use `employees(id, name, dept, salary)`.","answer":"```sql\nSELECT name FROM employees e\nWHERE salary > (\n  SELECT AVG(salary) FROM employees\n  WHERE dept = e.dept\n);\n```"},
  {"id":"c41-1","card":41,"cardTitle":"What are document/KV stores?","origin":"direct","tags":["conceptual","document_db"],"prompt":"What is a **document database**?","answer":"A database that stores flexible, JSON-like documents (e.g. MongoDB); each document can have its own shape."},
  {"id":"c41-2","card":41,"cardTitle":"What are document/KV stores?","origin":"direct","tags":["conceptual","document_db","relational"],"prompt":"How does a \"document\" differ from a row?","answer":"A document can nest related data inside itself; a row points to related data in other tables via foreign keys."},
  {"id":"c41-3","card":41,"cardTitle":"What are document/KV stores?","origin":"direct","tags":["conceptual","key_value"],"prompt":"What is a **key-value store**?","answer":"A giant dictionary: you look up a value instantly by its key."},
  {"id":"c41-4","card":41,"cardTitle":"What are document/KV stores?","origin":"direct","tags":["conceptual","key_value"],"prompt":"Give a use case for a key-value store.","answer":"Caching, e.g. using Redis to remember whether a card is due."},
  {"id":"c41-5","card":41,"cardTitle":"What are document/KV stores?","origin":"direct","tags":["conceptual","document_db","join"],"prompt":"Why might you embed related data in one document instead of joining tables?","answer":"Embedding avoids JOINs and is fast to read as one unit (e.g. a card with its tags embedded)."},
  {"id":"c41-6","card":41,"cardTitle":"What are document/KV stores?","origin":"direct","tags":["conceptual","document_db","normalization","anomaly"],"prompt":"What is a downside of embedding, compared with relational normalization?","answer":"The same embedded fact (e.g. a tag's description) can get duplicated across documents: the redundancy problem normalization solved, right back again."},
  {"id":"c42-1","card":42,"cardTitle":"Syntax for document queries?","origin":"direct","tags":["syntax_pattern","document_db"],"prompt":"Write the syntax pattern (Mongo-style) for a document representing a card with embedded tags.","answer":"```js\n{\n  \"_id\": 1,\n  \"question\": \"What is a JOIN?\",\n  \"answer\": \"Combines rows from two tables on a matching column.\",\n  \"tags\": [\"syntax\", \"joins\"]\n}\n```"},
  {"id":"c42-2","card":42,"cardTitle":"Syntax for document queries?","origin":"direct","tags":["syntax_pattern","document_db"],"prompt":"Write the syntax pattern for finding documents matching a field.","answer":"```js\ndb.cards.find({ \"question\": \"What is a JOIN?\" })\n```"},
  {"id":"c42-3","card":42,"cardTitle":"Syntax for document queries?","origin":"direct","tags":["writing_prompt","document_db"],"prompt":"Write a document for \"What is a JOIN?\" with its tags embedded directly, and a query that finds it by question text.","answer":"```js\n// A document (not a row!)\n{\n  \"_id\": 1,\n  \"question\": \"What is a JOIN?\",\n  \"answer\": \"Combines rows from two tables on a matching column.\",\n  \"tags\": [\"syntax\", \"joins\"]\n}\n\n// Query: find by question\ndb.cards.find({ \"question\": \"What is a JOIN?\" })\n```"},
  {"id":"c42-4","card":42,"cardTitle":"Syntax for document queries?","origin":"inferred","tags":["writing_prompt","document_db"],"prompt":"Write a Mongo-style query that finds every card whose `tags` array contains \"joins\".","answer":"```js\ndb.cards.find({ \"tags\": \"joins\" })\n```"},
  {"id":"c42-5","card":42,"cardTitle":"Syntax for document queries?","origin":"inferred","tags":["syntax_pattern","document_db"],"prompt":"Write a Mongo-style statement that adds this card to the `cards` collection: `_id` 1, question \"What is a JOIN?\", answer \"Combines rows from two tables on a matching column.\", tags \"syntax\" and \"joins\".","answer":"```js\ndb.cards.insertOne({\n  \"_id\": 1,\n  \"question\": \"What is a JOIN?\",\n  \"answer\": \"Combines rows from two tables on a matching column.\",\n  \"tags\": [\"syntax\", \"joins\"]\n})\n```"},
  {"id":"c43-1","card":43,"cardTitle":"Syntax for key-value lookups?","origin":"direct","tags":["syntax_pattern","key_value"],"prompt":"Write the syntax pattern for setting a key-value pair.","answer":"```text\nSET card:1:due_today true\n```"},
  {"id":"c43-2","card":43,"cardTitle":"Syntax for key-value lookups?","origin":"direct","tags":["syntax_pattern","key_value"],"prompt":"Write the syntax pattern for getting a value by key.","answer":"```text\nGET card:1:due_today\n-- -> true\n```"},
  {"id":"c43-3","card":43,"cardTitle":"Syntax for key-value lookups?","origin":"direct","tags":["writing_prompt","key_value"],"prompt":"Use a key-value store to cache \"card #1 is due today\" so the app doesn't have to query `reviews` every time it renders the study screen.","answer":"```text\nSET card:1:due_today true\nGET card:1:due_today\n-- -> true\n\nDEL card:1:due_today\n```"},
  {"id":"c43-4","card":43,"cardTitle":"Syntax for key-value lookups?","origin":"inferred","tags":["syntax_pattern","key_value"],"prompt":"Write the syntax pattern for removing a key.","answer":"```text\nDEL card:1:due_today\n```"},
  {"id":"c43-5","card":43,"cardTitle":"Syntax for key-value lookups?","origin":"inferred","tags":["conceptual","key_value"],"prompt":"Why is it useful to cache the \"due today\" flag in a key-value store instead of querying `reviews` each time?","answer":"A key-value lookup is a single fast read by key, while the query would have to search and filter the `reviews` table every time the study screen renders."},
  {"id":"c43-6","card":43,"cardTitle":"Syntax for key-value lookups?","origin":"inferred","tags":["conceptual","key_value"],"prompt":"In the key `card:1:due_today`, what is the colon-separated naming convention doing?","answer":"It encodes structure in a flat key space: the type of thing (`card`), its id (`1`), and the field (`due_today`), so keys stay unique and easy to guess."},
  {"id":"c44-1","card":44,"cardTitle":"Fluency with document/KV stores?","origin":"inferred","tags":["design","document_db"],"prompt":"Design a \"recipe\" domain as an embedded document instead of normalized tables. What would you nest?","answer":"One document per recipe with its ingredients nested inside, e.g. `{ \"name\": \"Pancakes\", \"ingredients\": [ { \"item\": \"flour\", \"qty\": \"2 cups\" }, ... ], \"steps\": [ ... ] }`."},
  {"id":"c44-2","card":44,"cardTitle":"Fluency with document/KV stores?","origin":"inferred","tags":["conceptual","key_value"],"prompt":"Identify one piece of data in a recipe app you would cache in a key-value store, and why.","answer":"For example \"recipe of the day\" or a user's session: it is read very often and by one simple key, so a fast key-value lookup avoids hitting the main database."},
  {"id":"c44-3","card":44,"cardTitle":"Fluency with document/KV stores?","origin":"inferred","tags":["conceptual","document_db"],"prompt":"A recipe app stores each recipe as one document with its ingredients embedded inside it. When would that design start to break down as the app grows?","answer":"When the same data (e.g. an ingredient's details) is embedded in many documents, so changing it means editing every copy, or when you need to query across recipes by shared ingredients."},
  {"id":"c44-4","card":44,"cardTitle":"Fluency with document/KV stores?","origin":"inferred","tags":["design","document_db"],"prompt":"A recipe app stores each recipe as one document. Write a second recipe document with a slightly different shape from `{ \"name\": \"Pancakes\", \"ingredients\": [...], \"steps\": [...] }`, and say what stays flexible.","answer":"For example a recipe with an extra `\"serves\": 4` field and no `\"steps\"`. Documents in a collection don't have to share the same fields."},
  {"id":"c44-5","card":44,"cardTitle":"Fluency with document/KV stores?","origin":"inferred","tags":["design","relational","join","normalization"],"prompt":"A recipe app stores each recipe as one document with its ingredients and steps embedded. If you rewrote that design as normalized tables, which tables would you need and how many JOINs would reading one full recipe take?","answer":"At least `recipes`, `ingredients`, and a junction table `recipe_ingredients` (plus `steps` if they are kept): reading a full recipe takes about two or three JOINs."},
  {"id":"c45-1","card":45,"cardTitle":"What is a graph database?","origin":"direct","tags":["conceptual","graph_db"],"prompt":"What is a **node** in a graph database?","answer":"An entity (e.g. a Card, a Tag, a Deck)."},
  {"id":"c45-2","card":45,"cardTitle":"What is a graph database?","origin":"direct","tags":["conceptual","graph_db"],"prompt":"What is an **edge** in a graph database?","answer":"A labeled, directed relationship connecting two nodes (e.g. `TAGGED`, `PREREQUISITE_OF`)."},
  {"id":"c45-3","card":45,"cardTitle":"What is a graph database?","origin":"direct","tags":["conceptual","graph_db","relational","join"],"prompt":"How is a graph database different from a relational database with foreign keys?","answer":"Relational stores relationships as foreign key *values*; graphs store relationships as first-class connections you can traverse directly, without JOINs."},
  {"id":"c45-4","card":45,"cardTitle":"What is a graph database?","origin":"direct","tags":["conceptual","graph_db"],"prompt":"What kind of question is a graph database especially good at answering?","answer":"Questions about deep or variable-length connections, e.g. \"every card you should review before this one, and everything before those.\""},
  {"id":"c45-5","card":45,"cardTitle":"What is a graph database?","origin":"direct","tags":["conceptual","graph_db"],"prompt":"Give an example of a node and an edge in this flashcard domain.","answer":"Node: `(Card)` or `(Tag)`. Edge: `(Card)-[:PREREQUISITE_OF]->(Card)` or `(Card)-[:TAGGED]->(Tag)`."},
  {"id":"c46-1","card":46,"cardTitle":"Syntax for graph nodes/edges?","origin":"direct","tags":["syntax_pattern","graph_db"],"prompt":"Write the syntax pattern (Cypher-style) for creating a node.","answer":"```cypher\nCREATE (a:Card {question: 'What is a loop?'})\n```"},
  {"id":"c46-2","card":46,"cardTitle":"Syntax for graph nodes/edges?","origin":"direct","tags":["syntax_pattern","graph_db"],"prompt":"Write the syntax pattern for creating an edge between two nodes.","answer":"```cypher\nCREATE (a)-[:PREREQUISITE_OF]->(b)\n```"},
  {"id":"c46-3","card":46,"cardTitle":"Syntax for graph nodes/edges?","origin":"direct","tags":["writing_prompt","graph_db"],"prompt":"Create two Card nodes (\"What is a loop?\" and \"What is a nested loop?\") and a `PREREQUISITE_OF` edge showing the first must be learned before the second.","answer":"```cypher\nCREATE (a:Card {question: 'What is a loop?'})\nCREATE (b:Card {question: 'What is a nested loop?'})\nCREATE (a)-[:PREREQUISITE_OF]->(b)\n```"},
  {"id":"c46-4","card":46,"cardTitle":"Syntax for graph nodes/edges?","origin":"inferred","tags":["conceptual","graph_db"],"prompt":"In `(a)-[:PREREQUISITE_OF]->(b)`, which card must be learned first, and what does the arrow's direction mean?","answer":"`a` must be learned first. The arrow runs from `a` to `b`, so the relationship reads \"a is a prerequisite of b\"."},
  {"id":"c46-5","card":46,"cardTitle":"Syntax for graph nodes/edges?","origin":"inferred","tags":["conceptual","graph_db"],"prompt":"In `(a:Card {question: 'What is a loop?'})`, what are `a`, `Card`, and the braces?","answer":"`a` is a variable naming the node, `Card` is its label (its type), and the braces hold its properties (here `question`)."},
  {"id":"c46-6","card":46,"cardTitle":"Syntax for graph nodes/edges?","origin":"inferred","tags":["writing_prompt","graph_db"],"prompt":"Card nodes \"What is a loop?\" and \"What is a nested loop?\" are linked by a `PREREQUISITE_OF` edge. Add a third card \"What is recursion?\" that has \"What is a nested loop?\" as a prerequisite.","answer":"```cypher\nMATCH (b:Card {question: 'What is a nested loop?'})\nCREATE (c:Card {question: 'What is recursion?'})\nCREATE (b)-[:PREREQUISITE_OF]->(c)\n```"},
  {"id":"c47-1","card":47,"cardTitle":"Syntax for graph pattern matching?","origin":"direct","tags":["syntax_pattern","graph_db"],"prompt":"Write the syntax pattern for matching a simple relationship.","answer":"```cypher\nMATCH (a:Card)-[:PREREQUISITE_OF]->(b:Card)\nRETURN a.question, b.question;\n```"},
  {"id":"c47-2","card":47,"cardTitle":"Syntax for graph pattern matching?","origin":"direct","tags":["syntax_pattern","graph_db"],"prompt":"Write the syntax pattern for a multi-hop match (a prerequisite chain).","answer":"```cypher\nMATCH (a:Card)-[:PREREQUISITE_OF*]->(b:Card)\nRETURN a.question, b.question;\n```"},
  {"id":"c47-3","card":47,"cardTitle":"Syntax for graph pattern matching?","origin":"direct","tags":["writing_prompt","graph_db"],"prompt":"Write a query that finds every direct prerequisite of \"What is a nested loop?\".","answer":"```cypher\nMATCH (prereq:Card)-[:PREREQUISITE_OF]->\n      (:Card {question: 'What is a nested loop?'})\nRETURN prereq.question;\n```"},
  {"id":"c47-4","card":47,"cardTitle":"Syntax for graph pattern matching?","origin":"direct","tags":["writing_prompt","graph_db"],"prompt":"Write a query that finds the *entire* chain of prerequisites of \"What is a nested loop?\", however many hops deep.","answer":"```cypher\nMATCH (prereq:Card)-[:PREREQUISITE_OF*]->\n      (:Card {question: 'What is a nested loop?'})\nRETURN DISTINCT prereq.question;\n```"},
  {"id":"c47-5","card":47,"cardTitle":"Syntax for graph pattern matching?","origin":"inferred","tags":["conceptual","graph_db"],"prompt":"What does the `*` in `-[:PREREQUISITE_OF*]->` mean?","answer":"Follow that kind of edge any number of times (one or more hops), so the pattern walks the whole chain."},
  {"id":"c47-6","card":47,"cardTitle":"Syntax for graph pattern matching?","origin":"inferred","tags":["conceptual","graph_db"],"prompt":"Why does the chain query use `RETURN DISTINCT`?","answer":"A card can be reachable by more than one path, so without `DISTINCT` it could be returned several times."},
  {"id":"c48-1","card":48,"cardTitle":"Fluency with graph databases?","origin":"inferred","tags":["design","graph_db","er_modeling"],"prompt":"Sketch the nodes and edges for a \"course prerequisites\" domain.","answer":"Nodes: `(Course)`. Edges: `(Course)-[:PREREQUISITE_OF]->(Course)`. Optionally add `(Student)` nodes with `(Student)-[:COMPLETED]->(Course)` edges."},
  {"id":"c48-2","card":48,"cardTitle":"Fluency with graph databases?","origin":"inferred","tags":["writing_prompt","graph_db"],"prompt":"Write a Cypher-style query that finds every course a student must take before \"CS330\", however many hops back.","answer":"```cypher\nMATCH (c:Course)-[:PREREQUISITE_OF*]->(:Course {title: 'CS330'})\nRETURN DISTINCT c.title;\n```"},
  {"id":"c48-3","card":48,"cardTitle":"Fluency with graph databases?","origin":"inferred","tags":["conceptual","graph_db","relational","join"],"prompt":"How would the number of JOINs needed to find every prerequisite of a course, at any depth, compare in a relational schema with the graph version?","answer":"The relational version needs one self-JOIN per hop, so a chain of unknown length can't be written as a fixed number of JOINs (it needs a recursive query). The graph query handles any depth."},
  {"id":"c48-4","card":48,"cardTitle":"Fluency with graph databases?","origin":"inferred","tags":["writing_prompt","graph_db"],"prompt":"Write a Cypher-style query that finds courses with no incoming `PREREQUISITE_OF` edges (courses with no prerequisites).","answer":"```cypher\nMATCH (c:Course)\nWHERE NOT ( ()-[:PREREQUISITE_OF]->(c) )\nRETURN c.title;\n```"},
  {"id":"c48-5","card":48,"cardTitle":"Fluency with graph databases?","origin":"inferred","tags":["design","relational","graph_db"],"prompt":"Sketch the course-prerequisite data as relational tables instead.","answer":"A `courses` table (id, title) and a `prerequisites` table (course_id, prereq_id), both columns being foreign keys to `courses`."},
  {"id":"c49-1","card":49,"cardTitle":"Where does a DB fit in an app?","origin":"direct","tags":["conceptual","app_architecture"],"prompt":"Trace one request through a web app: where does the **database** sit relative to the **browser** and the **web server**?","answer":"Browser -> web server (your application code) -> database -> back out as HTML or JSON. Only the web server talks to the database."},
  {"id":"c49-2","card":49,"cardTitle":"Where does a DB fit in an app?","origin":"direct","tags":["conceptual","app_architecture"],"prompt":"Why is the database its own separate process, instead of part of the web server?","answer":"Many web servers can share one database, and each can be restarted, moved, or scaled on its own."},
  {"id":"c49-3","card":49,"cardTitle":"Where does a DB fit in an app?","origin":"direct","tags":["conceptual","app_architecture"],"prompt":"What is a **connection** in application code?","answer":"An open session between application code and the database."},
  {"id":"c49-4","card":49,"cardTitle":"Where does a DB fit in an app?","origin":"direct","tags":["conceptual","app_architecture"],"prompt":"Why do apps keep a **pool** of connections?","answer":"Opening a connection is slow, so apps hold a pool of connections open and lend one to each request."},
  {"id":"c49-5","card":49,"cardTitle":"Where does a DB fit in an app?","origin":"direct","tags":["conceptual","app_architecture","security"],"prompt":"Why should the browser never connect to the database directly?","answer":"It would need the database password, and could then run *any* query, ignoring every rule the app enforces."},
  {"id":"c50-1","card":50,"cardTitle":"Syntax for querying from app code?","origin":"direct","tags":["syntax_pattern","app_architecture"],"prompt":"Write the syntax pattern for connecting to a database from application code.","answer":"```text\nconnection = connect(\"postgres://user:pass@localhost:5432/flashcards\")\n```"},
  {"id":"c50-2","card":50,"cardTitle":"Syntax for querying from app code?","origin":"direct","tags":["syntax_pattern","app_architecture","security","select"],"prompt":"Write the syntax pattern for a query whose value comes from the user (a **parameter**).","answer":"```text\nrows = connection.query(\n  \"SELECT question, answer FROM cards WHERE deck_id = ?\",\n  [params.id]\n)\n```"},
  {"id":"c50-3","card":50,"cardTitle":"Syntax for querying from app code?","origin":"direct","tags":["writing_prompt","app_architecture","select"],"prompt":"Write the server-side code behind `GET /decks/:id/cards`: connect, fetch that deck's cards with the id passed in as a parameter, and return them to the browser.","answer":"```text\nconnection = connect(\"postgres://user:pass@localhost:5432/flashcards\")\n\n-- Endpoint: GET /decks/:id/cards   (pseudocode)\nrows = connection.query(\n  \"SELECT question, answer FROM cards WHERE deck_id = ?\",\n  [params.id]\n)\nreturn json(rows)\n```"},
  {"id":"c50-4","card":50,"cardTitle":"Syntax for querying from app code?","origin":"inferred","tags":["conceptual","security","app_architecture"],"prompt":"What is SQL injection?","answer":"An attack where user input is glued into a query string so that the input is interpreted as SQL, letting the attacker run queries the app never intended."},
  {"id":"c50-5","card":50,"cardTitle":"Syntax for querying from app code?","origin":"inferred","tags":["debugging","security","app_architecture"],"prompt":"What is dangerous about `\"SELECT ... WHERE deck_id = \" + params.id`, and what is the fix?","answer":"User input becomes part of the SQL text, which allows SQL injection. Pass the value as a parameter instead (`WHERE deck_id = ?` with `[params.id]`) so it is always treated as data."},
  {"id":"c51-1","card":51,"cardTitle":"Syntax for choosing a DB type?","origin":"direct","tags":["design","relational","document_db","key_value","graph_db"],"prompt":"Write out a checklist you'd use to pick relational vs. document vs. key-value vs. graph for a new feature.","answer":"Ask: Is the data structured and does it need integrity (keys, constraints, complex queries)? -> relational. Is each item self-contained with a flexible shape? -> document. Is it a simple lookup by one key, needing speed? -> key-value. Are the relationships themselves the point, deep or variable-length? -> graph."},
  {"id":"c51-2","card":51,"cardTitle":"Syntax for choosing a DB type?","origin":"direct","tags":["design","key_value","document_db"],"prompt":"Which type of store would you pick for a shopping cart, and why?","answer":"Key-value (or document): a cart is looked up by one key (the user or session) and read and written as a single unit, with no complex relationships."},
  {"id":"c51-3","card":51,"cardTitle":"Syntax for choosing a DB type?","origin":"direct","tags":["design","document_db","relational"],"prompt":"Which type of store would you pick for a product catalog, and why?","answer":"Document (items have varying attributes and are read as one unit) or relational (if the catalog needs strong integrity and complex queries)."},
  {"id":"c51-4","card":51,"cardTitle":"Syntax for choosing a DB type?","origin":"direct","tags":["design","graph_db"],"prompt":"Which type of store would you pick for a social network's \"who follows whom\", and why?","answer":"Graph: the follow relationships are the data, and questions like \"friends of friends\" need multi-hop traversal."},
  {"id":"c51-5","card":51,"cardTitle":"Syntax for choosing a DB type?","origin":"direct","tags":["design","relational"],"prompt":"For the flashcard app, which database type would you assign to the catalog of decks, cards, tags, and reviews, and why?","answer":"Relational: the data is structured, needs integrity (foreign keys, constraints), and supports complex queries."},
  {"id":"c51-6","card":51,"cardTitle":"Syntax for choosing a DB type?","origin":"direct","tags":["design","key_value"],"prompt":"For the flashcard app, which database type would you assign to a \"card is due today\" flag cache, and why?","answer":"Key-value: a single fast lookup, with no relationships needed."},
  {"id":"c51-7","card":51,"cardTitle":"Syntax for choosing a DB type?","origin":"direct","tags":["design","graph_db"],"prompt":"For the flashcard app, which database type would you assign to a prerequisite-chain feature (\"what should I review before this card?\"), and why?","answer":"Graph: it needs deep, variable-length relationship traversal."},
  {"id":"c52-1","card":52,"cardTitle":"Fluency in databases?","origin":"inferred","tags":["design","relational","document_db","key_value","graph_db"],"prompt":"Pick an app idea of your own and say which of its pieces would be relational, document, key-value, or graph, and why.","answer":"Any consistent answer, e.g. for a recipe app: users and saved recipes (relational), recipe pages with nested steps (document), a session or \"popular today\" cache (key-value), and \"recipes that use similar ingredients\" (graph)."},
  {"id":"c52-2","card":52,"cardTitle":"Fluency in databases?","origin":"inferred","tags":["conceptual","app_architecture"],"prompt":"Trace one feature of an app you've designed from the browser, through the web server, to the database and back.","answer":"The browser sends a request; the web server runs the app code, which takes a connection from the pool and runs a parameterized query; the database returns rows; the server turns them into HTML or JSON; the browser displays them."},
  {"id":"c52-3","card":52,"cardTitle":"Fluency in databases?","origin":"inferred","tags":["design","app_architecture"],"prompt":"Write a short pitch for an app's data architecture, covering the \"why\" behind each database choice.","answer":"A good answer names each data store, says what kind of data and access pattern it serves, and justifies the choice (e.g. relational for the integrity-critical core, key-value for hot lookups)."},
  {"id":"c52-4","card":52,"cardTitle":"Fluency in databases?","origin":"inferred","tags":["conceptual","relational","document_db","key_value","graph_db"],"prompt":"Give an example of something that could go wrong if you chose the wrong database type for a feature.","answer":"For example, storing a deep follower network in relational tables forces many JOINs and slow queries; using a key-value store for data that needs complex queries and constraints forces the app to implement them by hand."},
  {"id":"c52-5","card":52,"cardTitle":"Fluency in databases?","origin":"inferred","tags":["conceptual","app_architecture"],"prompt":"How might an app's data architecture need to change if it went from 100 users to 1,000,000?","answer":"Likely: caching with a key-value store, connection pooling, read replicas or sharding for the main database, and moving hot or high-volume features to a store better suited to that access pattern."},
  {"id":"c52-6","card":52,"cardTitle":"Fluency in databases?","origin":"inferred","tags":["writing_prompt","app_architecture","select","security"],"prompt":"Write the server-side code for an endpoint `GET /cards/:id` that looks up one card, passing the id in as a parameter.","answer":"```text\n-- Endpoint: GET /cards/:id   (pseudocode)\nrows = connection.query(\n  \"SELECT question, answer FROM cards WHERE id = ?\",\n  [params.id]\n)\nreturn json(rows)\n```"}
]);
